'use strict';
(() => {
const S = window.AdminStore;
const J = window.NirvivadJourney;
const C = window.NirvivadContact;
const $ = (q, root=document) => root.querySelector(q);
const $$ = (q, root=document) => Array.from(root.querySelectorAll(q));
const esc = value => String(value ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',users:'<circle cx="9" cy="7" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 4a3 3 0 0 1 0 6M18 13a5 5 0 0 1 3 5v3"/>',layers:'<path d="m12 3 10 5-10 5L2 8l10-5ZM2 12l10 5 10-5M2 16l10 5 10-5"/>',card:'<rect x="2" y="5" width="20" height="14" rx="2"/><path d="M2 10h20M6 15h4"/>',file:'<path d="M14 3H5v18h14V8l-5-5Zm0 0v5h5M8 12h8M8 16h6"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3Z"/><path d="m8 12 3 3 5-6"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 22v-3a8 8 0 0 1 16 0v3"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3M12 14v3"/>',logout:'<path d="M9 3H4v18h5M9 12h12m-4-4 4 4-4 4"/>',arrow:'<path d="M5 19 19 5M5 5h14v14"/>',plus:'<path d="M12 4v16M4 12h16"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',edit:'<path d="m15 4 5 5-11 11-6 1 1-6L15 4Zm-3 3 5 5"/>',eye:'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7-10-7-10-7Z"/><circle cx="12" cy="12" r="3"/>',trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7M14 10v7"/>',check:'<path d="m5 12 4 4L19 6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',menu:'<path d="M3 6h18M3 12h18M3 18h18"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',tree:'<rect x="9" y="2" width="6" height="5" rx="1"/><rect x="2" y="17" width="6" height="5" rx="1"/><rect x="16" y="17" width="6" height="5" rx="1"/><path d="M12 7v5H5v5M12 12h7v5"/>'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[n]||paths.file}</svg>`;
const brand=()=>`<a class="brand" href="../index.html"><img src="../assets/nirvivad-mark.svg" width="39" height="44" alt=""><span>Nirvivad<small>PROPERTY. WITH CLARITY.</small></span></a>`;
const initials=name=>esc(String(name||'NV').split(/\s+/).filter(Boolean).slice(0,2).map(x=>x[0]).join('').toUpperCase());
const labelRole=role=>S.roles[role]||role;
const badge=(active,text)=>`<span class="pill ${active?'active':'inactive'}">${esc(text||(active?'Active':'Inactive'))}</span>`;
const date=value=>value?new Date(value).toLocaleDateString('en-IN',{day:'2-digit',month:'short',year:'numeric'}):'—';
const dateTime=value=>value?new Date(value).toLocaleString('en-IN',{dateStyle:'medium',timeStyle:'short'}):'—';
const money=value=>value===null||value===''||value===undefined?'Not configured':new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:2}).format(Number(value));
const link=(text,href,cls='button',ic='')=>`<a class="${cls}" href="${esc(href)}">${ic?icon(ic):''}${esc(text)}</a>`;
const button=(text,action,attrs='',cls='button secondary',ic='')=>`<button type="button" class="${cls}" data-action="${action}" ${attrs}>${ic?icon(ic):''}${esc(text)}</button>`;
const heading=(eyebrow,title,description,actions='')=>`<div class="page-heading"><div><p class="eyebrow">${esc(eyebrow)}</p><h1>${esc(title)}</h1><p>${esc(description)}</p></div><div class="heading-actions">${actions}</div></div>`;
const notice=(text,cls='notice')=>`<div class="${cls}">${icon('shield')}<span>${esc(text)}</span></div>`;
const empty=(title,text)=>`<div class="empty-state">${icon('layers')}<h3>${esc(title)}</h3><p>${esc(text)}</p></div>`;
const formError=()=>'<div class="error-message" id="form-error" role="alert" tabindex="-1" hidden></div>';
const field=(name,label,value='',opts={})=>`<div class="field ${opts.full?'full':''}"><label for="field-${name}">${esc(label)}${opts.required?' <span class="required">*</span>':''}</label><input id="field-${name}" name="${name}" type="${opts.type||'text'}" value="${esc(value)}" ${opts.required?'required':''} ${opts.max?`maxlength="${opts.max}"`:''} ${opts.min!==undefined?`min="${opts.min}"`:''} ${opts.step?`step="${opts.step}"`:''} ${opts.disabled?'disabled':''} ${opts.autocomplete?`autocomplete="${opts.autocomplete}"`:''} ${opts.placeholder?`placeholder="${esc(opts.placeholder)}"`:''}>${opts.help?`<span class="field-help">${esc(opts.help)}</span>`:''}</div>`;
const textarea=(name,label,value='',opts={})=>`<div class="field ${opts.full?'full':''}"><label for="field-${name}">${esc(label)}${opts.required?' *':''}</label><textarea id="field-${name}" name="${name}" rows="${opts.rows||3}" maxlength="${opts.max||2000}" ${opts.required?'required':''}>${esc(value)}</textarea>${opts.help?`<span class="field-help">${esc(opts.help)}</span>`:''}</div>`;
const select=(name,label,value,options,opts={})=>`<div class="field ${opts.full?'full':''}"><label for="field-${name}">${esc(label)}${opts.required?' *':''}</label><select id="field-${name}" name="${name}" ${opts.required?'required':''} ${opts.disabled?'disabled':''}>${options.map(o=>{const [v,t]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(t)}</option>`;}).join('')}</select>${opts.help?`<span class="field-help">${esc(opts.help)}</span>`:''}</div>`;
const check=(name,label,value=false,help='')=>`<div class="check-field"><input type="checkbox" id="field-${name}" name="${name}" ${value?'checked':''}><label for="field-${name}">${esc(label)}${help?`<span class="field-help">${esc(help)}</span>`:''}</label></div>`;
let lastHash=location.hash;
let state={page:'overview',params:new URLSearchParams(),dirty:false,query:'',role:'all',status:'all',manager:'all',tablePage:1}, toastTimer, confirmation=null, savedSelection=null;
function toast(text){$('#toast').textContent=text;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,4000);}
function current(){return S.currentUser();}
function managerName(u){return u.managerName||(S.getState().managerOptions||[]).find(m=>m.id===u.managerId)?.name||S.getState().users.find(m=>m.id===u.managerId)?.name||'Not assigned';}
function canUser(action,u){const me=current();if(!me||!S.can('users',action))return false;if(action==='assign'&&me.role!=='superadmin')return false;if(u.role==='superadmin')return action==='view';return me.role==='superadmin'||(me.role==='subadmin'&&u.role==='employee'&&u.managerId===me.id&&u.id!==me.id);}
function closeMenu(){document.body.classList.remove('sidebar-open');$('#menu-toggle')?.setAttribute('aria-expanded','false');const shade=$('#nav-shade');if(shade)shade.hidden=true;}
function dialog(title,body,actions=''){const d=$('#admin-dialog');d.innerHTML=`<div class="dialog-header"><h2 id="dialog-title">${esc(title)}</h2><button class="icon-button close-dialog" data-action="close-dialog" aria-label="Close dialog">${icon('close')}</button></div><div class="dialog-body">${body}</div>${actions?`<div class="dialog-actions">${actions}</div>`:''}`;d.showModal();}
function confirmAction(title,text,fn,destructive=false){confirmation=fn;dialog(title,`<p>${esc(text)}</p>`,button('Cancel','close-dialog','', 'button secondary')+button('Confirm','confirm','',`button ${destructive?'danger':''}`));}
function report(error){const el=$('#form-error');if(el){el.textContent=error.message||String(error);el.hidden=false;el.focus();}else toast(error.message||String(error));}
function loginView(error=''){
 const accounts=S.demoAccounts||[];
 $('#app').innerHTML=`<div class="login-layout"><section class="login-story"><div class="login-mark">${brand()}</div><div><p class="login-kicker">NIRVIVAD ADMINISTRATION</p><h1>A clear structure.<br>A stronger foundation.</h1><p>Your people, permissions and platform essentials. Connected in one considered workspace.</p><div class="login-points"><div>${icon('users')}<span>One team. Defined responsibilities.</span></div><div>${icon('shield')}<span>Access that follows your role.</span></div><div>${icon('layers')}<span>Consistent data. Confident decisions.</span></div></div></div><small>Administration Management · Module 01</small></section><section class="login-main"><div class="login-card">${brand()}<p class="eyebrow">WELCOME TO YOUR WORKSPACE</p><h2>Sign in to Administration</h2><p>Use your work email and password to continue.</p><form id="login-form">${formError()}${field('email','Email address','',{type:'email',required:true,autocomplete:'username',max:160,placeholder:'you@nirvivad.example'})}<div class="field"><label for="field-password">Password *</label><div class="password-field"><input id="field-password" name="password" type="password" autocomplete="current-password" required maxlength="128"><button type="button" class="icon-button" data-action="toggle-password" data-for="field-password" aria-label="Show password">${icon('eye')}</button></div></div><button class="button" type="submit">Sign in ${icon('arrow')}</button></form><details class="demo-access"><summary>Explore with a demo account</summary><p>Local prototype. Use sample information only; account checks and changes run in this browser.</p>${accounts.filter(a=>['sa@nirvivad.example','subadmin@nirvivad.example','employee@nirvivad.example'].includes(a.email)).map(a=>`<button type="button" class="demo-account" data-action="fill-demo" data-email="${esc(a.email)}"><span><strong>${esc(labelRole(a.role))}</strong><code>${esc(a.email)}</code></span>${icon('arrow')}</button>`).join('')}<p>Demo password: <code>Nirvivad@123</code></p></details><div class="login-footer"><a href="../index.html">← Back to the website</a><span>Email + Password</span></div></div></section></div>`;
 if(error){$('#form-error').textContent=error;$('#form-error').hidden=false;}
}
function navItem(href,text,ic,isActive){return `<a class="nav-item" href="${href}" ${isActive?'aria-current="page"':''}><span class="nav-icon">${icon(ic)}</span><span>${text}</span></a>`;}
function shell(content){const u=current();const page=state.page;const masterKeys=Object.keys(S.masterTypes);const firstMaster=masterKeys.find(k=>S.can(k,'view'));const usersActive=['users','user','user-edit','permissions'].includes(page);
 $('#app').innerHTML=`<div class="admin-shell"><aside class="sidebar" id="sidebar"><div class="sidebar-brand">${brand()}</div><div class="workspace-label"><span>ADMINISTRATION</span><span class="pill blue">01</span></div><nav aria-label="Administration navigation"><div class="nav-group-label">WORKSPACE</div>${navItem('#overview','Overview','grid',page==='overview')}${navItem('#prototype-summary','Prototype summary','file',page==='prototype-summary')}${S.can('users','view')?navItem('#users',u.role==='subadmin'?'My team':'Users & hierarchy','users',usersActive):''}${u.role==='superadmin'?navItem('#customers','Customer accounts','users',['customers','customer','partner-create'].includes(page)):''}<div class="nav-group-label">REQUEST WORKFLOWS</div>${navItem('#requests?kind=property','Property submissions','home',['requests','request'].includes(page)&&state.params.get('kind')!=='enquiry')}${navItem('#requests?kind=enquiry','Buyer enquiries','users',['requests','request'].includes(page)&&state.params.get('kind')==='enquiry')}${navItem('#contacts','Contact enquiries','file',['contacts','contact-enquiry'].includes(page))}<div class="nav-group-label">PLATFORM SETTINGS</div>${firstMaster?navItem('#masters?kind='+firstMaster,'Master data','layers',['masters','master-edit'].includes(page)):''}${S.can('subscriptions','view')?navItem('#plans','Subscriptions','card',['plans','plan','plan-edit'].includes(page)):''}${S.can('cms','view')?navItem('#cms','CMS pages','file',['cms','cms-edit','cms-preview'].includes(page)):''}<div class="nav-group-label">MY ACCOUNT</div>${navItem('#profile','My profile','user',['profile','profile-edit'].includes(page))}${navItem('#password','Change password','lock',page==='password')}</nav><div class="sidebar-bottom"><div class="session-note">${icon('shield')}<div><strong>${esc(labelRole(u.role))}</strong><span>${u.role==='superadmin'?'Full administration access':u.role==='subadmin'?'Your assigned team':'Your assigned permissions'}</span></div></div><button class="nav-item" data-action="logout">${icon('logout')}<span>Sign out</span></button><small>Local administration prototype</small></div></aside><button class="nav-shade" id="nav-shade" aria-label="Close navigation" hidden></button><div class="workspace"><header class="topbar"><button id="menu-toggle" class="icon-button menu-toggle" data-action="menu" aria-expanded="false" aria-controls="sidebar" aria-label="Toggle navigation">${icon('menu')}</button><div class="breadcrumb">Administration <span>/</span> <strong>${esc(pageLabels[page]||'Overview')}</strong></div><div class="topbar-spacer"></div><a href="../index.html" class="site-link">View website ${icon('arrow')}</a><a href="#profile" class="profile-button"><span class="avatar">${initials(u.name)}</span><span class="profile-meta"><strong>${esc(u.name)}</strong><small>${esc(labelRole(u.role))}</small></span></a></header><main id="main" class="page-content" tabindex="-1">${content}</main><footer class="admin-footer"><span>© ${new Date().getFullYear()} Nirvivad</span><span>Administration Management</span></footer></div></div>`;
}
const pageLabels={'partner-create':'Create NV Channel Partner','prototype-summary':'Prototype summary',contacts:'Contact enquiries','contact-enquiry':'Contact enquiry',requests:'Requests',request:'Request details',customers:'Customer accounts',customer:'Customer details',overview:'Overview',users:'Users & hierarchy',user:'User details','user-edit':'Manage user',permissions:'Role & permissions',masters:'Master data','master-edit':'Manage master entry',plans:'Subscriptions',plan:'Plan details','plan-edit':'Manage plan',cms:'CMS pages','cms-edit':'Content editor','cms-preview':'Content preview',profile:'My profile','profile-edit':'Edit profile',password:'Change password'};
function overview(){const u=current();const data=S.getState();const users=data.users||[];const masters=Object.values(data.masters||{}).flat();const plans=data.plans||[];const cms=data.cms||[];const activities=(data.audit||[]).slice(0,6);
 const cards=[['users',u.role==='employee'?'Your account':'Team members',u.role==='employee'?1:users.length,u.role==='subadmin'?'Your visible team':'Across your access scope'],['layers','Master entries',masters.length,'Reference data you can access'],['card','Subscription plans',plans.length,`${plans.filter(p=>p.active).length} active plans`],['shield','Account status',u.active?'Active':'Inactive',labelRole(u.role)+(u.alsoEmployee?' + Employee':'')]];
 const actions=[];if(S.can('users','create'))actions.push(['users','Add a team member','Create an account and assign a manager.','#user-edit']);if(Object.keys(S.masterTypes).some(k=>S.can(k,'view')))actions.push(['layers','Explore master data','Manage the platform’s reference values.','#masters']);if(S.can('subscriptions','view'))actions.push(['card','Review subscription plans','Annual plans and their configured benefits.','#plans']);if(S.can('cms','view'))actions.push(['file','Manage policy pages','Review, edit and publish policy content.','#cms']);
 return heading('YOUR ADMINISTRATION WORKSPACE',`Welcome back, ${u.name.split(' ')[0]}.`,'Keep your people, platform data and permissions in good order.',link('My profile','#profile','button secondary','user'))+`<div class="stats-grid">${cards.map(([i,t,n,d])=>`<article class="stat-card"><span class="stat-icon">${icon(i)}</span><span class="stat-label">${t}</span><strong class="stat-value">${n}</strong><span class="stat-note">${esc(d)}</span></article>`).join('')}</div><div class="dashboard-grid"><section class="card"><div class="card-header"><div><h2>Your next step</h2><p>The essentials for a well-organised platform.</p></div></div><div class="card-body"><div class="quick-actions">${actions.map(([i,t,d,h])=>`<a href="${h}" class="quick-action"><span class="quick-icon">${icon(i)}</span><div><h3>${t}</h3><p>${d}</p></div>${icon('arrow')}</a>`).join('')}</div></div></section><section class="card"><div class="card-header"><h2>Your access</h2></div><div class="card-body"><span class="pill blue">${esc(labelRole(u.role))}</span><h3 style="margin-top:20px">A clear reporting line</h3><p class="muted">${u.role==='superadmin'?'You oversee Sub Admins, Employees and platform configuration.':`Manager: ${esc(managerName(u))}. Your access stays within your assigned responsibilities.`}</p>${u.alsoEmployee?notice('Employee capability is enabled on your Sub Admin account.'):''}${link('View role & access','#profile','button secondary small','shield')}</div></section></div><section class="card"><div class="card-header"><div><h2>Recent administration activity</h2><p>Changes visible within your access scope.</p></div>${icon('clock')}</div><div class="card-body">${activities.length?`<div class="activity-list">${activities.map(a=>`<div class="activity-row"><span class="activity-dot"></span><div><strong>${esc(a.summary||a.action)}</strong><div class="activity-meta">${esc(a.actorName||'Administration')} · ${date(a.at||a.timestamp||a.createdAt)}</div></div></div>`).join('')}</div>`:empty('A fresh start','Your administration changes will appear here.')}</div></section>`;
}
function prototypeSummary(){const sections=[
 ['Account entry & roles',['Customer entry uses one mobile number and a demo OTP. New customers provide a name, optional email, and joining role; without a selection they start as Buyer / Investor. Returning customers reopen their last used role.','One customer account can hold Buyer / Investor, Property Owner, Lawyer, Chartered Accountant, Broker, Arbitrator, and Builder / Developer roles. NV Channel Partner is assigned only by Super Admin. The first joining role and later additions stay visible in Administration.','Administration has a separate email/password sign-in for Super Admin, Sub Admin, and Employee, with team assignments and scoped access.']],
 ['KYC & professional approval',['Aadhaar and PAN basic KYC is completed once per customer and reused across customer roles. Optional identity attachment names and masked identifiers are recorded.','Lawyer, CA, Broker, Arbitrator and Builder / Developer profiles collect proposed credentials and document names. A Super Admin approves or returns a submitted profile before its role workspace can be used. Broker, Arbitrator and Builder / Developer sample profiles are seeded for review.']],
 ['Property Owner journey',['An Owner creates a property through a four-stage stepper, saves a draft, and submits basic details into the team queue. Drafts expire under the prototype timer.','The Employee reviews a submitted property and selects missing FRD fields or document categories. Already supplied or pending items are marked, so the Owner only answers the request.','The Owner sees relevant progress, requested actions, submitted sample file previews, and a timeline of visible updates. Internal remarks and professional reports stay with the team.']],
 ['Scoped role assignments',['An Employee can assign an approved Lawyer, CA, Broker, NV Channel Partner, Arbitrator or Builder / Developer with an explicit list of shared fields and submitted documents. More than one person can be assigned in the same role. The team can select individual report sections, optional report attachments, and internal notes while hiding the other assignee’s identity and contact details. An Owner cannot review their own property through another role.','After submission, assigning the same account creates a numbered follow-up round. Earlier assignments and reports stay read-only. The professional sees only assigned, selected case information and submits a role-specific report. Administration sees the full case, report, and activity trail.']],
 ['Buyer enquiry journey',['Buyers complete basic KYC before browsing approved, limited property listings. An enquiry is linked to the listing and enters the Administration queue.','The team assigns, reviews, requests information, adds internal remarks and follow-ups, and sends Buyer-visible updates. An approved Broker or NV Partner can receive a scoped market-support task, with a new follow-up round after each submitted update. The Buyer sees their own status, requests, and update timeline.','Administration enquiry pages have Details, Actions & requests, Market support, and Activity trail tabs. The audit records Buyer and team actions; older enquiry history is labelled where actor details were unavailable.']],
 ['Website Contact Us',['The public Contact Us form requires a mobile number, allows optional email, and saves a validated enquiry with a reference and received time in this browser.','Administration lists messages in a separate Contact enquiries queue and records team status changes. A customer verified with the submitted mobile can view their own messages and statuses. Server delivery and cross-device sharing remain future work.']],
 ['Other Administration screens',['Users and hierarchy, customer role and review filters, reference master data, subscription plans, CMS policy pages, profile settings, and password changes are available according to staff role.','Property and enquiry cases use responsive tabs. Team assignment, status changes, requests, responses, professional reports, and remarks are recorded in case history.']]
 ];return heading('PROJECT RECORD','Prototype summary','A read-only record of the journeys and Administration features available in this browser prototype.')+`<div class="summary-intro card"><div class="card-body"><span class="pill blue">Current prototype</span><p>This page describes implemented demo behaviour. It is a reference for review and the next phase, not a live customer data report.</p><div class="summary-quicklinks">${link('Property queue','#requests?kind=property','button secondary small')}${link('Buyer enquiries','#requests?kind=enquiry','button secondary small')}${link('Contact enquiries','#contacts','button secondary small')}${current().role==='superadmin'?link('Customer accounts','#customers','button secondary small'):''}</div></div></div><div class="prototype-summary-grid">${sections.map(([title,items],i)=>`<section class="card summary-card"><div class="card-body"><span class="summary-number">${String(i+1).padStart(2,'0')}</span><h2>${esc(title)}</h2><ul>${items.map(item=>`<li>${esc(item)}</li>`).join('')}</ul></div></section>`).join('')}</div><section class="card summary-limitations"><div class="card-body"><h2>Current prototype boundaries</h2><p>Data and sample document previews live in this browser only. The OTP is a demo code; credential and identity checks, payments, file uploads to a server, server-side access control, and durable audit storage are future implementation work.</p><p>The FRD names property fields, while the final mandatory document matrix and Lawyer/CA report templates still need client confirmation.</p></div></section>`}
function usersPage(){const u=current();return heading('PEOPLE & RESPONSIBILITIES',u.role==='subadmin'?'Your team, clearly connected.':'The right people. The right access.','Manage internal accounts, reporting lines and account access.',S.can('users','create')?link('Add user','#user-edit','button','plus'):'')+`<div class="tabs"><button class="tab ${state.params.get('view')!=='hierarchy'?'active':''}" data-action="user-tab" data-view="list">${icon('users')} User directory</button><button class="tab ${state.params.get('view')==='hierarchy'?'active':''}" data-action="user-tab" data-view="hierarchy">${icon('tree')} Reporting hierarchy</button></div>${u.role==='subadmin'?notice('You can manage Employees assigned directly to you. Only Super Admin can move users between managers or change their roles and permissions.','permission-note'):''}<section class="card"><div class="toolbar"><label class="search-box">${icon('search')}<input type="search" id="list-search" placeholder="Search name, email or department" aria-label="Search users" value="${esc(state.query)}"></label><div class="filters"><select id="filter-role" aria-label="Filter by role"><option value="all">All roles</option>${Object.entries(S.roles).map(([v,t])=>`<option value="${v}" ${state.role===v?'selected':''}>${esc(t)}</option>`).join('')}</select><select id="filter-status" aria-label="Filter by status"><option value="all">All statuses</option><option value="active" ${state.status==='active'?'selected':''}>Active</option><option value="inactive" ${state.status==='inactive'?'selected':''}>Inactive</option></select><button class="button ghost small" data-action="reset-filters">Reset</button></div></div><div id="listing-content"></div><div id="pagination"></div></section>`;}
function filteredUsers(){return S.listUsers().filter(u=>(state.role==='all'||u.role===state.role)&&(state.status==='all'||u.active===(state.status==='active'))&&[u.name,u.email,u.department,u.designation].join(' ').toLowerCase().includes(state.query.toLowerCase()));}
function paintUsers(){const users=filteredUsers();const hierarchy=state.params.get('view')==='hierarchy';const size=10;const pages=Math.max(1,Math.ceil(users.length/size));state.tablePage=Math.min(state.tablePage,pages);const subset=hierarchy?users:users.slice((state.tablePage-1)*size,state.tablePage*size);
 if(!users.length)$('#listing-content').innerHTML=empty('No users found','Try another search or clear your filters.');
 else if(hierarchy){const all=S.listUsers();const ordered=[];const visit=(person,seen=new Set())=>{if(seen.has(person.id))return;seen.add(person.id);ordered.push(person);all.filter(c=>c.managerId===person.id).forEach(c=>visit(c,seen));};all.filter(p=>!all.some(m=>m.id===p.managerId)).forEach(p=>visit(p));const selected=new Set(subset.map(p=>p.id));$('#listing-content').innerHTML=`<div class="hierarchy-list">${ordered.filter(u=>selected.has(u.id)).map(u=>`<a class="hierarchy-item" href="#user?id=${encodeURIComponent(u.id)}" style="--level:${u.role==='superadmin'?0:u.role==='subadmin'?1:2}"><span class="avatar">${initials(u.name)}</span><div><strong>${esc(u.name)}</strong><span class="manager-name">${esc(labelRole(u.role))}${u.alsoEmployee?' + Employee':''} ${u.managerId?' · Reports to '+esc(managerName(u)):''}</span></div>${badge(u.active)}${icon('arrow')}</a>`).join('')}</div>`;}
 else $('#listing-content').innerHTML=`<div class="table-wrap"><table class="data-table"><thead><tr><th>User</th><th>Role</th><th>Manager</th><th>Status</th><th>Actions</th></tr></thead><tbody>${subset.map(u=>`<tr><td><div class="person-cell"><span class="avatar">${initials(u.name)}</span><div class="person-meta"><strong>${esc(u.name)}</strong><span>${esc(u.email)}</span></div></div></td><td><span class="pill blue">${esc(labelRole(u.role))}</span>${u.alsoEmployee?'<small class="muted"> + Employee</small>':''}</td><td>${u.managerId?esc(managerName(u)):'—'}</td><td>${badge(u.active)}</td><td><div class="table-actions">${link('View','#user?id='+encodeURIComponent(u.id),'button ghost small')}${canUser('edit',u)?link('Edit','#user-edit?id='+encodeURIComponent(u.id),'button ghost small'):''}${canUser('status',u)?button(u.active?'Deactivate':'Activate','user-status',`data-id="${esc(u.id)}"`,'button ghost small'):''}</div></td></tr>`).join('')}</tbody></table></div>`;
 $('#pagination').innerHTML=`<div class="pagination"><span>${users.length} ${users.length===1?'user':'users'}${hierarchy?' in the reporting view':''}</span>${!hierarchy?`<div>${button('Previous','page-prev',state.tablePage<=1?'disabled':'','button ghost small')}<span>Page ${state.tablePage} of ${pages}</span>${button('Next','page-next',state.tablePage>=pages?'disabled':'','button ghost small')}</div>`:''}</div>`;
}
function userDetails(){const u=S.getUser(state.params.get('id'));const me=current();const actions=link('Back to users','#users','button ghost small')+(canUser('edit',u)?link('Edit user','#user-edit?id='+encodeURIComponent(u.id),'button','edit'):'');
 return heading('USER DIRECTORY',u.name,'Account details, reporting line and assigned access.',actions)+`<div class="detail-grid"><section class="card detail-card"><div class="card-body"><div class="profile-summary"><span class="avatar large">${initials(u.name)}</span><div><h2>${esc(u.name)}</h2><p>${esc(u.email)}</p>${badge(u.active)}</div></div><dl class="detail-list"><dt>Role</dt><dd>${esc(labelRole(u.role))}${u.alsoEmployee?' + Employee':''}</dd><dt>Manager</dt><dd>${u.managerId?esc(managerName(u)):'Top-level administrator'}</dd><dt>Phone</dt><dd>${esc(u.phone||'Not supplied')}</dd><dt>Department</dt><dd>${esc(u.department||'Not supplied')}</dd><dt>Designation</dt><dd>${esc(u.designation||'Not supplied')}</dd><dt>Created</dt><dd>${date(u.createdAt)}</dd><dt>Last updated</dt><dd>${date(u.updatedAt)}</dd></dl></div></section><section class="card detail-card"><div class="card-header"><h2>Role & permissions</h2>${icon('shield')}</div><div class="card-body"><p class="muted">${u.role==='superadmin'?'Super Admin has full access to this Administration module.':u.role==='subadmin'?'Team management stays limited to direct-report Employees.':'Access is limited to the modules and actions assigned to this account.'}</p>${permissionSummary(u)}${me.role==='superadmin'&&u.role!=='superadmin'?link('Assign role & permissions','#permissions?id='+encodeURIComponent(u.id),'button secondary','shield'):''}${canUser('assign',u)?link('Assign manager','#user-edit?id='+encodeURIComponent(u.id)+'&focus=manager','button secondary','tree'):''}</div></section></div>${canUser('delete',u)?`<section class="card"><div class="card-body"><h2>Account controls</h2><p class="muted">Deactivate an account to stop access while retaining its details. Users with direct reports must be reassigned before their manager is removed.</p><div class="heading-actions">${canUser('status',u)?button(u.active?'Deactivate account':'Activate account','user-status',`data-id="${esc(u.id)}"`):''}${button('Delete user','user-delete',`data-id="${esc(u.id)}"`,'button danger','trash')}</div></div></section>`:''}`;
}
function permissionSummary(u){if(u.role==='superadmin')return '<div class="role-summary"><strong>Full Administration access</strong><p>You can manage internal users, reporting lines, permissions, all six masters, subscription plans and policy content.</p></div>';const overrides=Object.entries(u.permissions||{}).flatMap(([r,v])=>Object.entries(v).map(([a,on])=>`${S.permissionResources[r]?.label||r}: ${a} ${on?'allowed':'denied'}`));return `<div class="role-summary"><strong>${overrides.length?'Individual permission overrides':'Role defaults apply'}</strong><p>${overrides.length?overrides.map(esc).join('<br>'):'Master data and subscriptions are view-only for Sub Admins and Employees by default. CMS editing stays with Super Admin.'}</p></div>`;}
function managerOptions(role,id=null){return [['','Select a manager'],...S.listManagers(role,id).map(m=>[m.id,`${m.name} · ${labelRole(m.role)}`])];}
function userForm(){const id=state.params.get('id');const u=id?S.getUser(id):{name:'',email:'',phone:'',role:current().role==='subadmin'?'employee':'subadmin',managerId:current().id,active:true,alsoEmployee:false,department:'',designation:''};if(id&&!canUser('edit',u))throw Error('You do not have permission to edit this user.');if(!id&&!S.can('users','create'))throw Error('You do not have permission to create users.');const limited=current().role!=='superadmin';
 return heading('USER MANAGEMENT',id?'Edit user':'Add a team member','Create a clear role and reporting line from the start.',link('Back to users','#users','button secondary'))+`<form id="user-form" class="form-card card" data-id="${esc(id||'')}"><div class="card-body">${formError()}<h2 class="form-section-title">Account details</h2><div class="form-grid">${field('name','Full name',u.name,{required:true,max:100,autocomplete:'name'})}${field('email','Work email',u.email,{type:'email',required:true,max:160,autocomplete:'off'})}${field('phone','Phone number',u.phone,{type:'tel',max:25})}${field('designation','Designation',u.designation,{max:100})}${field('department','Department',u.department,{max:100})}${!id?field('password','Initial password','',{type:'password',required:true,max:128,autocomplete:'new-password',help:'At least 10 characters with uppercase, lowercase, a number and a symbol.'}):''}</div><h2 class="form-section-title">Role & reporting line</h2><div class="form-grid">${select('role','Primary role',u.role,limited?[['employee','Employee']]:[['subadmin','Sub Admin'],['employee','Employee']],{required:true,disabled:limited})}${select('managerId','Manager',u.managerId,managerOptions(u.role,id),{required:true,disabled:limited,help:limited?'Employees you create report directly to you.':'Sub Admins report to Super Admin. Employees can report to an active Sub Admin or Super Admin.'})}<div class="field full" id="employee-capability" ${u.role!=='subadmin'?'hidden':''}>${check('alsoEmployee','Also act as an Employee',u.alsoEmployee,'Keep the Sub Admin role and reporting line while enabling Employee capability for future work.')}</div><div class="field full">${check('active','Active account',u.active,'Inactive accounts cannot sign in.')}</div></div>${notice('Permissions start from role defaults. Super Admin can assign individual permissions after the account is created.','permission-note')}</div><div class="form-actions">${link('Cancel',id?'#user?id='+encodeURIComponent(id):'#users','button secondary')}<button type="submit" class="button">${id?'Save changes':'Create user'} ${icon('check')}</button></div></form>`;
}
function permissionsPage(){const u=S.getUser(state.params.get('id'));if(current().role!=='superadmin'||u.role==='superadmin')throw Error('Only Super Admin can assign permissions to Sub Admins and Employees.');
 return heading('ACCESS MANAGEMENT',`Permissions for ${u.name}`,'Apply role defaults or override individual module actions.',link('Back to user','#user?id='+encodeURIComponent(u.id),'button secondary'))+`<form id="permissions-form" class="card form-card" data-id="${esc(u.id)}"><div class="card-body">${formError()}<div class="profile-summary"><span class="avatar">${initials(u.name)}</span><div><h2>${esc(u.name)}</h2><p>${esc(labelRole(u.role))} · ${esc(u.email)}</p></div>${link('Change role or manager','#user-edit?id='+encodeURIComponent(u.id),'button secondary small')}</div>${notice('An override never expands a Sub Admin beyond their assigned Employees. Employees cannot gain administrative user management. CMS remains Super Admin-only.','permission-note')}<div class="permission-legend"><span><strong>Role default</strong> follows the primary role.</span><span><strong>Allow / Deny</strong> is an explicit override.</span></div><div class="table-wrap"><table class="data-table permission-table"><thead><tr><th>Module</th>${['view','create','edit','delete','status'].map(x=>`<th>${x==='status'?'Activate / deactivate':x.charAt(0).toUpperCase()+x.slice(1)}</th>`).join('')}</tr></thead><tbody>${Object.entries(S.permissionResources).filter(([k])=>k!=='cms'&&(k!=='users'||u.role==='subadmin')).map(([r,m])=>`<tr><th scope="row">${esc(m.label)}</th>${['view','create','edit','delete','status'].map(a=>`<td><select name="perm:${r}:${a}" aria-label="${esc(m.label)} ${a} permission"><option value="inherit">Role default</option><option value="allow" ${u.permissions?.[r]?.[a]===true?'selected':''}>Allow</option><option value="deny" ${u.permissions?.[r]?.[a]===false?'selected':''}>Deny</option></select></td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="field-help">Allowing an action also requires View for that module. Manager assignment and permission delegation remain Super Admin actions.</p></div><div class="form-actions">${button('Restore role defaults','reset-permissions','','button ghost')}<button type="submit" class="button">Save permissions ${icon('check')}</button></div></form>`;
}
function masterKind(){return state.params.get('kind')||Object.keys(S.masterTypes).find(k=>S.can(k,'view'))||'land';}
function masterTabs(kind){return `<nav class="master-tabs" aria-label="Master data categories">${Object.entries(S.masterTypes).filter(([k])=>S.can(k,'view')).map(([k,m])=>`<a href="#masters?kind=${k}" ${k===kind?'aria-current="page" class="active"':''}>${esc(m.label)}</a>`).join('')}</nav>`;}
function mastersPage(){const k=masterKind();if(!S.masterTypes[k]||!S.can(k,'view'))throw Error('You do not have access to this master data section.');const records=S.listMaster(k);return heading('MASTER DATA',S.masterTypes[k].label,'Maintain consistent reference values across the platform.',S.can(k,'create')?link('Add entry','#master-edit?kind='+k,'button','plus'):'')+masterTabs(k)+`${!S.can(k,'edit')?notice('You have view-only access to this master. Additional actions require assigned permissions.','permission-note'):''}<section class="card"><div class="toolbar"><label class="search-box">${icon('search')}<input id="list-search" type="search" placeholder="Search name or code" aria-label="Search master entries" value="${esc(state.query)}"></label><div class="filters"><select id="filter-status" aria-label="Filter status"><option value="all">All statuses</option><option value="active" ${state.status==='active'?'selected':''}>Active</option><option value="inactive" ${state.status==='inactive'?'selected':''}>Inactive</option></select><span class="master-summary">${records.length} entries</span></div></div><div id="listing-content"></div><div id="pagination"></div></section>`;}
function paintMasters(){const k=masterKind();const rows=S.listMaster(k).filter(x=>(state.status==='all'||x.active===(state.status==='active'))&&[x.name,x.code,x.description].join(' ').toLowerCase().includes(state.query.toLowerCase()));const pages=Math.max(1,Math.ceil(rows.length/10));state.tablePage=Math.min(state.tablePage,pages);const items=rows.slice((state.tablePage-1)*10,state.tablePage*10);
 $('#listing-content').innerHTML=rows.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Name</th><th>Code</th>${k==='unit'?'<th>Symbol</th>':''}<th>Order</th><th>Status</th><th>Actions</th></tr></thead><tbody>${items.map(m=>`<tr><td><strong>${esc(m.name)}</strong>${m.requiresDetails?'<small class="muted">Additional details required</small>':''}</td><td><code>${esc(m.code)}</code></td>${k==='unit'?`<td>${esc(m.symbol||'—')}</td>`:''}<td>${m.sortOrder||0}</td><td>${badge(m.active)}</td><td><div class="table-actions">${button('View','master-view',`data-id="${esc(m.id)}" data-kind="${k}"`,'button ghost small')}${S.can(k,'edit')?link('Edit','#master-edit?kind='+k+'&id='+encodeURIComponent(m.id),'button ghost small'):''}${S.can(k,'status')?button(m.active?'Deactivate':'Activate','master-status',`data-id="${esc(m.id)}" data-kind="${k}"`,'button ghost small'):''}${S.can(k,'delete')?button('Delete','master-delete',`data-id="${esc(m.id)}" data-kind="${k}"`,'button ghost small'):''}</div></td></tr>`).join('')}</tbody></table></div>`:empty('No entries found','Try another search, or add a new reference value.');
 $('#pagination').innerHTML=`<div class="pagination"><span>${rows.length} entries</span><div>${button('Previous','page-prev',state.tablePage<=1?'disabled':'','button ghost small')}<span>Page ${state.tablePage} of ${pages}</span>${button('Next','page-next',state.tablePage>=pages?'disabled':'','button ghost small')}</div></div>`;
}
function masterForm(){const k=masterKind();const id=state.params.get('id');if(!S.can(k,id?'edit':'create'))throw Error('You do not have permission for this action.');const m=id?S.listMaster(k).find(x=>x.id===id):{name:'',code:'',description:'',sortOrder:0,active:true,requiresDetails:false,symbol:''};if(!m)throw Error('This entry could not be found.');return heading('MASTER DATA',id?'Edit '+S.masterTypes[k].label:'Add '+S.masterTypes[k].label,'Use a clear, unique name and a stable reference code.',link('Back to master data','#masters?kind='+k,'button secondary'))+`<form class="card form-card" id="master-form" data-id="${esc(id||'')}" data-kind="${k}"><div class="card-body">${formError()}<div class="form-grid">${field('name','Name',m.name,{required:true,max:100})}${field('code','Code',m.code,{required:true,max:30,help:'Unique in this master. Use letters, numbers, underscores or hyphens.'})}${textarea('description','Description',m.description,{full:true,max:1000})}${field('sortOrder','Display order',m.sortOrder,{type:'number',min:0,step:1,required:true})}${k==='unit'?field('symbol','Display symbol',m.symbol,{max:12,help:'Optional. Regional unit conversions are not assumed.'}):''}<div class="field full">${check('active','Active entry',m.active)}</div><div class="field full">${check('requiresDetails','Ask for additional details when selected',m.requiresDetails,'Useful for “Others (Mention detail)” values.')}</div></div></div><div class="form-actions">${link('Cancel','#masters?kind='+k,'button secondary')}<button class="button" type="submit">Save entry ${icon('check')}</button></div></form>`;}
function plansPage(){if(!S.can('subscriptions','view'))throw Error('You do not have access to subscriptions.');return heading('SUBSCRIPTION MANAGEMENT','Plans with a clear purpose.','Configure annual property listing plans, pricing and benefits.',S.can('subscriptions','create')?link('Create plan','#plan-edit','button','plus'):'')+notice('Workbook plans are seeded with 1 and 5 property posts per year. Unspecified prices and benefits remain unset; configure a price before activation.','permission-note')+`<div class="toolbar"><label class="search-box">${icon('search')}<input id="list-search" type="search" placeholder="Search plan name or code" value="${esc(state.query)}" aria-label="Search subscription plans"></label><div class="filters"><select id="filter-status" aria-label="Filter plan status"><option value="all">All statuses</option><option value="active" ${state.status==='active'?'selected':''}>Active</option><option value="inactive" ${state.status==='inactive'?'selected':''}>Inactive</option></select>${!S.can('subscriptions','edit')?'<span class="pill blue">View-only access</span>':''}</div></div><div id="listing-content"></div>`;}
function paintPlans(){const plans=S.listPlans().filter(p=>(state.status==='all'||p.active===(state.status==='active'))&&[p.name,p.code].join(' ').toLowerCase().includes(state.query.toLowerCase()));$('#listing-content').innerHTML=plans.length?`<div class="subscription-grid">${plans.map(p=>`<article class="subscription-card"><div class="plan-top"><span class="eyebrow">${esc(p.code)}</span>${badge(p.active)}</div><h2>${esc(p.name)}</h2><p class="muted">${esc(p.description||'Property listing membership')}</p><div class="plan-count">${p.propertyLimit}<span> property ${Number(p.propertyLimit)===1?'post':'posts'}</span></div><div class="plan-price">${money(p.price)} <span>/ ${p.durationMonths} months</span></div><ul class="feature-list">${Object.entries(S.planFeatures).slice(0,5).map(([key,label])=>`<li><span>${esc(label)}</span><strong>${esc(p.features?.[key]||'Not specified')}</strong></li>`).join('')}</ul><div class="plan-footer">${link('View plan','#plan?id='+encodeURIComponent(p.id),'button secondary small')}${S.can('subscriptions','edit')?link('Edit plan','#plan-edit?id='+encodeURIComponent(p.id),'button small','edit'):''}</div></article>`).join('')}</div>`:empty('No plans found','Try another search or create a subscription plan.');}
function planDetails(){const p=S.listPlans().find(x=>x.id===state.params.get('id'));if(!p)throw Error('Plan not found or access denied.');return heading('SUBSCRIPTION DETAILS',p.name,'Review the plan terms and configured benefits.',link('Back to plans','#plans','button secondary')+(S.can('subscriptions','edit')?link('Edit plan','#plan-edit?id='+encodeURIComponent(p.id),'button','edit'):''))+`<div class="detail-grid"><section class="card detail-card"><div class="card-header"><h2>Plan overview</h2>${badge(p.active)}</div><div class="card-body"><dl class="detail-list"><dt>Plan code</dt><dd>${esc(p.code)}</dd><dt>Duration</dt><dd>${p.durationMonths} months</dd><dt>Property posts</dt><dd>${p.propertyLimit}</dd><dt>Price</dt><dd>${money(p.price)}</dd><dt>Currency</dt><dd>INR</dd><dt>Description</dt><dd>${esc(p.description||'Not specified')}</dd><dt>Updated</dt><dd>${date(p.updatedAt)}</dd></dl><div class="heading-actions">${S.can('subscriptions','status')?button(p.active?'Deactivate plan':'Activate plan','plan-status',`data-id="${esc(p.id)}"`):''}${S.can('subscriptions','delete')?button('Delete plan','plan-delete',`data-id="${esc(p.id)}"`,'button danger'):''}</div></div></section><section class="card detail-card"><div class="card-header"><h2>Plan benefits</h2></div><div class="card-body"><dl class="detail-list">${Object.entries(S.planFeatures).map(([k,l])=>`<dt>${esc(l)}</dt><dd>${esc(p.features?.[k]||'Not specified')}</dd>`).join('')}</dl></div></section></div>${notice('The workbook’s “Confidentiality: No” is preserved as source plan text. It never changes the platform rule that owner identity is hidden from investors.','permission-note')}`;}
function planForm(){const id=state.params.get('id');if(!S.can('subscriptions',id?'edit':'create'))throw Error('You do not have permission to manage this plan.');const p=id?S.listPlans().find(x=>x.id===id):{name:'',code:'',description:'',durationMonths:12,propertyLimit:1,price:null,active:false,features:{}};if(!p)throw Error('This plan could not be found.');return heading('SUBSCRIPTION MANAGEMENT',id?'Edit subscription plan':'Create subscription plan','Keep unspecified values blank. Finalise pricing before activation.',link('Back to plans','#plans','button secondary'))+`<form id="plan-form" class="card form-card" data-id="${esc(id||'')}"><div class="card-body">${formError()}<h2 class="form-section-title">Plan details</h2><div class="form-grid">${field('name','Plan name',p.name,{required:true,max:100})}${field('code','Plan code',p.code,{required:true,max:30})}${textarea('description','Description',p.description,{full:true,max:1000})}${field('durationMonths','Duration in months',p.durationMonths,{type:'number',min:1,step:1,required:true})}${field('propertyLimit','Number of property posts',p.propertyLimit,{type:'number',min:1,step:1,required:true})}${field('price','Plan price (INR)',p.price??'',{type:'number',min:0,step:'.01',help:'Leave blank if not yet confirmed. Zero means a deliberately free plan.'})}<div class="field">${check('active','Active plan',p.active,'An active plan must have a configured price, duration and property limit.')}</div></div><h2 class="form-section-title">Benefits & service inclusions</h2><p class="muted">Values follow the workbook. Blank means not specified; use “No” only when explicitly excluded.</p><div class="form-grid features-grid">${Object.entries(S.planFeatures).map(([k,l])=>textarea('feature-'+k,l,p.features?.[k]||'',{max:500,rows:2})).join('')}</div>${notice('Confidentiality wording is descriptive plan data, not a control over owner privacy or role permissions.','permission-note')}</div><div class="form-actions">${link('Cancel',id?'#plan?id='+encodeURIComponent(id):'#plans','button secondary')}<button class="button" type="submit">Save plan ${icon('check')}</button></div></form>`;}
function cmsPage(){if(!S.can('cms','view'))throw Error('CMS management is available to Super Admin only.');const pages=S.listCms();return heading('CONTENT MANAGEMENT','Clear policies. Consistent information.','Manage Terms & Conditions, Privacy Policy and Payment Policy.')+notice('Save a draft for review, then publish it to the public policy page in this browser. Draft edits do not replace the last published version.','permission-note')+`<div class="cms-grid">${pages.map(p=>`<article class="cms-card"><span class="cms-icon">${icon('file')}</span><span class="pill ${p.status==='published'?'active':'draft'}">${p.status==='published'?'Published':'Draft'}</span><h2>${esc(p.title)}</h2><p class="muted">${p.slug==='terms'?'Platform terms and conditions.':p.slug==='privacy'?'How personal information is handled.':'Payment, cancellation and refund information.'}</p><div class="cms-meta">Last updated ${date(p.updatedAt)}${p.version?' · Version '+esc(p.version):''}</div><div class="plan-footer">${link('Preview','#cms-preview?slug='+p.slug,'button secondary small')}${link('Edit content','#cms-edit?slug='+p.slug,'button small','edit')}</div></article>`).join('')}</div>`;}
function cmsEditor(){if(!S.can('cms','edit'))throw Error('Only Super Admin can update policy pages.');const p=S.getCms(state.params.get('slug'));return heading('CMS EDITOR',p.title,'Format content, review your changes and publish when ready.',link('Back to CMS','#cms','button secondary'))+`<form id="cms-form" class="card form-card" data-slug="${esc(p.slug)}"><div class="card-body">${formError()}<div class="form-grid">${field('title','Page title',p.title,{required:true,max:120,full:true})}</div><div class="editor-toolbar" role="toolbar" aria-label="Content formatting"><button type="button" data-command="bold" aria-label="Bold"><strong>B</strong></button><button type="button" data-command="italic" aria-label="Italic"><em>I</em></button><button type="button" data-command="underline" aria-label="Underline"><u>U</u></button><select id="editor-format" aria-label="Text style"><option value="p">Paragraph</option><option value="h2">Heading</option><option value="h3">Subheading</option><option value="blockquote">Quote</option></select><button type="button" data-command="insertUnorderedList">Bullet list</button><button type="button" data-command="insertOrderedList">Numbered list</button><button type="button" data-command="removeFormat">Clear format</button><input type="url" id="editor-link" placeholder="https://example.com" aria-label="Link URL"><button type="button" data-action="editor-link">Add link</button></div><div id="cms-editor" class="rich-editor" contenteditable="true" role="textbox" aria-label="Policy content" aria-multiline="true" spellcheck="true">${S.sanitizeHtml(p.content)}</div><p class="field-help"><span id="editor-count">0</span> characters · Use headings, paragraphs and lists for a clear reading experience.</p>${notice('Content is sanitised when saved. Publishing makes this version visible on the corresponding public policy page in this browser.','permission-note')}</div><div class="form-actions">${button('Preview content','cms-preview-draft','','button secondary','eye')}<button class="button secondary" type="submit" name="intent" value="draft">Save draft</button><button class="button" type="submit" name="intent" value="published">Publish page ${icon('check')}</button></div></form>`;}
function cmsPreview(){const p=S.getCms(state.params.get('slug'));return heading('CONTENT PREVIEW',p.title,p.status==='published'?'Published content stored in this browser.':'Review the draft before publishing.',link('Back to CMS','#cms','button secondary')+link('Edit content','#cms-edit?slug='+p.slug,'button','edit'))+`<section class="card cms-preview"><div class="card-body"><span class="pill ${p.status==='published'?'active':'draft'}">${p.status==='published'?'Published':'Draft'}</span><article class="prose">${S.sanitizeHtml(p.content)}</article></div></section>`;}
function profile(){const u=current();return heading('MY ACCOUNT','Your profile. Your workspace.','Keep your contact details up to date and review your role.',link('Edit profile','#profile-edit','button','edit'))+`<div class="detail-grid"><section class="card detail-card"><div class="card-body"><div class="profile-summary"><span class="avatar large">${initials(u.name)}</span><div><h2>${esc(u.name)}</h2><p>${esc(u.email)}</p>${badge(u.active)}</div></div><dl class="detail-list"><dt>Primary role</dt><dd>${esc(labelRole(u.role))}</dd><dt>Employee capability</dt><dd>${u.role==='employee'||u.alsoEmployee?'Enabled':'Not assigned'}</dd><dt>Manager</dt><dd>${u.managerId?esc(managerName(u)):'Top-level administrator'}</dd><dt>Phone</dt><dd>${esc(u.phone||'Not supplied')}</dd><dt>Department</dt><dd>${esc(u.department||'Not supplied')}</dd><dt>Designation</dt><dd>${esc(u.designation||'Not supplied')}</dd><dt>Joined</dt><dd>${date(u.createdAt)}</dd></dl></div></section><section class="card detail-card"><div class="card-header"><h2>Account access</h2>${icon('shield')}</div><div class="card-body">${permissionSummary(u)}<p class="muted">Your role, manager and permissions are managed by an authorised administrator.</p>${link('Change password','#password','button secondary','lock')}</div></section></div>`;}
function profileEdit(){const u=current();return heading('MY ACCOUNT','Edit your profile','Update your contact details. Role and reporting changes are managed separately.',link('Back to profile','#profile','button secondary'))+`<form id="profile-form" class="card form-card"><div class="card-body">${formError()}<div class="form-grid">${field('name','Full name',u.name,{required:true,max:100,autocomplete:'name'})}${field('email','Work email',u.email,{required:true,type:'email',max:160,autocomplete:'email'})}${field('phone','Phone number',u.phone,{max:25,type:'tel',autocomplete:'tel'})}${field('department','Department',u.department,{max:100})}${field('designation','Designation',u.designation,{max:100})}</div></div><div class="form-actions">${link('Cancel','#profile','button secondary')}<button class="button" type="submit">Save profile ${icon('check')}</button></div></form>`;}
function passwordPage(){return heading('ACCOUNT SECURITY','Change your password','Choose a password unique to your Nirvivad account.',link('Back to profile','#profile','button secondary'))+`<form id="password-form" class="card form-card"><div class="card-body">${formError()}<div class="form-grid">${field('currentPassword','Current password','',{type:'password',required:true,max:128,autocomplete:'current-password',full:true})}${field('newPassword','New password','',{type:'password',required:true,max:128,autocomplete:'new-password',help:'At least 10 characters with uppercase, lowercase, a number and a symbol.'})}${field('confirmPassword','Confirm new password','',{type:'password',required:true,max:128,autocomplete:'new-password'})}</div>${notice('After your password changes, sign in again using the new password. Existing sessions will no longer be valid.','permission-note')}</div><div class="form-actions">${link('Cancel','#profile','button secondary')}<button class="button" type="submit">Update password ${icon('lock')}</button></div></form>`;}
function requestPage(){const kind=state.params.get('kind')==='enquiry'?'enquiry':'property';const rows=J.adminList(current(),kind);return heading('REQUEST WORKFLOWS',kind==='property'?'Property submissions':'Buyer enquiries','Only submitted requests enter the team queue.')+`<div class="tabs">${link('Property submissions','#requests?kind=property','button secondary')}${link('Buyer enquiries','#requests?kind=enquiry','button secondary')}</div><section class="card"><div class="table-wrap"><table class="data-table"><thead><tr><th>Reference</th><th>Summary</th><th>Status</th><th>Submitted</th><th>Action</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.id)}</td><td>${esc(kind==='property'?r.title||r.category:r.preview?.category+' · '+r.preview?.location)}</td><td>${badge(true,r.status.replaceAll('_',' '))}</td><td>${date(r.submittedAt||r.createdAt)}</td><td>${link('Review','#request?kind='+kind+'&id='+encodeURIComponent(r.id),'button ghost small')}</td></tr>`).join('')}</tbody></table></div>${rows.length?'':empty('No requests','Submitted requests will appear here.')}</section>`}
function attachmentLink(doc){if(!doc.contentDataUrl)return `<span class="muted">${esc(doc.name)} · Preview unavailable for an earlier submission</span>`;try{const match=/^data:([^;]+);base64,(.*)$/.exec(doc.contentDataUrl);if(!match||!['image/jpeg','image/png','image/webp','application/pdf'].includes(match[1]))return esc(doc.name);const bytes=Uint8Array.from(atob(match[2]),c=>c.charCodeAt(0));const url=URL.createObjectURL(new Blob([bytes],{type:match[1]}));return `<a class="attachment-preview ${match[1].startsWith('image/')?'is-image':'is-document'}" href="${url}" target="_blank" rel="noopener" aria-label="Open ${esc(doc.name)} in a new tab">${match[1].startsWith('image/')?`<img src="${url}" alt="Preview of ${esc(doc.name)}">`:'<span class="attachment-preview-icon" aria-hidden="true">PDF</span>'}<span class="attachment-preview-name">${esc(doc.name)} <span aria-hidden="true">↗</span></span></a>`}catch{return esc(doc.name)}}
function propertyCasePage(r,team,subs,employees){const tab=['details','actions','professionals','activity'].includes(state.params.get('tab'))?state.params.get('tab'):'details',base='#request?kind=property&id='+encodeURIComponent(r.id),parts=propertyWorkflow(r).match(/<section class="card">[\s\S]*?<\/section>/g)||[],labels={details:'Property details',actions:'Actions & requests',professionals:'Professionals',activity:'Activity trail'};const owner=r.contact?`<dt>Owner contact</dt><dd>${esc(r.contact.name)} · ${esc(r.contact.mobile)} · ${esc(r.contact.email||'No email')}</dd>`:'';const summary=`<section class="card detail-card"><div class="card-body"><h2>${esc(r.title||'Property submission')}</h2><dl class="detail-list"><dt>Status</dt><dd>${esc(r.status.replaceAll('_',' '))}</dd><dt>Property</dt><dd>${esc([r.category,r.location,r.state,r.area&&r.area+' '+(r.unit||'')].filter(Boolean).join(' · '))}</dd>${owner}<dt>Sub Admin</dt><dd>${esc(team.find(x=>x.id===r.subAdminId)?.name||r.subAdminId||'Unassigned')}</dd><dt>Employee</dt><dd>${esc(team.find(x=>x.id===r.employeeId)?.name||r.employeeId||'Unassigned')}</dd><dt>KYC</dt><dd>Aadhaar ${esc(r.kyc?.aadhaar||'pending')} · PAN ${esc(r.kyc?.pan||'pending')}</dd><dt>Subscription</dt><dd>${esc(r.subscription?.status||'pending')} · ${esc(r.subscription?.planId||'No plan')}</dd></dl></div></section>`;const process=`<section class="card detail-card"><div class="card-body"><h2>Process property</h2><form id="request-form" data-kind="property" data-id="${esc(r.id)}">${formError()}${current().role==='superadmin'?select('subAdminId','Assign Sub Admin',r.subAdminId||'',[['','Unassigned'],...subs.map(x=>[x.id,x.name])]):''}${current().role!=='employee'?select('employeeId','Assign Employee',r.employeeId||'',[['','Unassigned'],...employees.map(x=>[x.id,x.name])]):''}${select('status','Processing status',r.status,['submitted','under_review','additional_info','eligible_for_deal','published','on_hold','rejected'].filter(x=>current().role==='superadmin'||x===r.status||!['published','rejected'].includes(x)).map(x=>[x,x.replaceAll('_',' ')]) )}${textarea('remark','Internal remark','',{max:1200})}${textarea('followUp','Follow-up activity','',{max:500})}${textarea('request','General information request','',{max:500})}${textarea('update','Customer-visible update','',{max:500})}<button class="button" type="submit">Save request changes</button></form></div></section>`;const history=`<section class="card"><div class="card-body"><h2>Internal history</h2>${[['Assignments',r.assignmentHistory],['Status changes',r.statusHistory],['Internal remarks',r.internalRemarks],['Follow-ups',r.followUps],['Information requests',r.requests]].map(([label,rows])=>`<h3>${label}</h3><ul>${(rows||[]).map(x=>`<li>${esc(x.text||x.message||x.status||[x.subAdminId,x.employeeId].filter(Boolean).join(' → ')||'Updated')} · ${date(x.at||x.createdAt)}</li>`).join('')||'<li>None yet</li>'}</ul>`).join('')}</div></section>`;const panels={details:summary+(parts[0]||''),actions:process+(parts[1]||''),professionals:parts.slice(2,-1).join(''),activity:(parts.at(-1)||'')+history};return heading('REQUEST WORKFLOWS',r.id,'Review the property, take action, and follow its history.',link('Back to queue','#requests?kind=property','button secondary'))+`<nav class="property-case-tabs" aria-label="Property case sections">${Object.entries(labels).map(([key,label])=>`<a href="${base}&tab=${key}" ${key===tab?'aria-current="page"':''}>${label}</a>`).join('')}</nav><div class="property-case-panel">${panels[tab]}</div>`}
function propertyWorkflow(r){const actor=current(),canAssign=['employee','superadmin'].includes(actor.role),fields=J.propertyFields,docs=J.propertyDocuments,all={title:r.title,category:r.category,state:r.state,location:r.location,locality:r.locality,area:r.area,unit:r.unit,ownershipType:r.ownershipType,disputeType:r.disputeType,description:r.description,...r.additionalFields};const possible=Object.entries(all).filter(([,v])=>v).map(([k,v])=>[k,v]);const fieldLabel=k=>fields.find(x=>x.id===k)?.label||k;return `<section class="card"><div class="card-body"><h2>Complete property record</h2><dl class="detail-list">${possible.map(([k,v])=>`<dt>${esc(fieldLabel(k))}</dt><dd>${esc(v)}</dd>`).join('')}</dl><h3>Submitted documents</h3><ul>${(r.documents||[]).map(x=>`<li>${esc(docs.find(d=>d.id===x.typeId)?.label||x.typeId)}: ${attachmentLink(x)} · ${date(x.submittedAt)}</li>`).join('')||'<li>No documents submitted.</li>'}</ul></div></section><section class="card"><div class="card-body"><h2>Request additional information</h2><p>Select the FRD fields and document categories needed for this property.</p><form id="property-items-form" data-id="${esc(r.id)}">${formError()}<div class="workflow-checks"><fieldset><legend>Fields</legend>${fields.map(x=>{const value=all[x.id]||r.details?.[x.id],pending=(r.requests||[]).some(q=>q.status==='pending'&&q.fieldIds?.includes(x.id));return `<label class="${value?'workflow-provided':''}"><input type="checkbox" name="fieldIds" value="${x.id}" ${value||pending?'disabled':''}> ${esc(x.label)} ${value?'· Already provided':pending?'· Already requested':''}</label>`}).join('')}</fieldset><fieldset><legend>Documents</legend>${docs.map(x=>{const value=(r.documents||[]).some(d=>d.typeId===x.id),pending=(r.requests||[]).some(q=>q.status==='pending'&&q.documentTypeIds?.includes(x.id));return `<label class="${value?'workflow-provided':''}"><input type="checkbox" name="documentTypeIds" value="${x.id}" ${value||pending?'disabled':''}> ${esc(x.label)} ${value?'· Already provided':pending?'· Already requested':''}</label>`}).join('')}</fieldset></div>${textarea('message','Request note','',{max:500})}<button class="button" type="submit">Send selected request</button></form><h3>Request responses</h3>${(r.requests||[]).filter(q=>q.fieldIds?.length||q.documentTypeIds?.length).map(q=>`<p><strong>${esc(q.status)}</strong> · ${esc(q.message)} · ${esc([...(q.fieldIds||[]).map(fieldLabel),...(q.documentTypeIds||[]).map(k=>docs.find(x=>x.id===k)?.label||k)].join(', '))}</p>`).join('')||'<p>No structured requests.</p>'}</div></section>${['lawyer','ca','broker','partner','arbitrator','builder'].map(role=>{const tasks=[...(r.professionalTasks?.[role]?[r.professionalTasks[role]]:[]),...(r.professionalTasksExtra?.[role]||[])],people=canAssign?J.approvedProfessionals(actor,role).filter(x=>x.id!==r.ownerId):[];const reportChoices=Object.entries(J.roleDefinitions).flatMap(([sourceRole])=>[...(r.professionalTasks?.[sourceRole]?[r.professionalTasks[sourceRole]]:[]),...(r.professionalTasksExtra?.[sourceRole]||[])].filter(t=>t.report).map(t=>({id:sourceRole+':'+t.accountId+(Number(t.round||1)>1?':round:'+t.round:''),role:sourceRole,report:t.report,label:J.roleDefinitions[sourceRole].label+' report · Round '+(t.round||1)+' · '+(canAssign?(J.approvedProfessionals(actor,sourceRole).find(x=>x.id===t.accountId)?.name||'Assigned user'):'Assigned user')})));return `<section class="card"><div class="card-body"><h2>${esc(J.roleDefinitions[role].label)} ${role==='builder'?'response':'review'}</h2>${tasks.length?tasks.map((task,index)=>`<div class="assigned-review"><h3>Round ${esc(task.round||1)}: ${esc(people.find(x=>x.id===task.accountId)?.name||task.accountId)} · ${esc(task.status)}</h3>${task.followUpTo?'<p class="muted">Follow-up review; earlier report retained.</p>':''}<p>Shared fields: ${esc(task.fieldIds.map(fieldLabel).join(', ')||'None')}</p><p>Shared documents: ${esc(task.documentIds.map(id=>r.documents?.find(x=>x.id===id)?.name||id).join(', ')||'None')}</p><p>Shared reports: ${esc((task.reportIds||[]).length)} · Team notes: ${esc((task.remarkIndexes||[]).length)}</p>${task.report?`<h4>Submitted report</h4>${Object.entries(task.report).filter(([k])=>!['by','submittedAt','attachment'].includes(k)).map(([k,v])=>`<p><strong>${esc(k)}:</strong> ${esc(v||'—')}</p>`).join('')+(task.report.attachment?`<p><strong>Attachment:</strong> ${attachmentLink(task.report.attachment)}</p>`:'')}`:''}</div>`).join(''):'<p>Not assigned.</p>'}${canAssign?`<form class="professional-assignment-form" data-id="${esc(r.id)}" data-role="${role}">${formError()}<label>Approved ${esc(J.roleDefinitions[role].label)}<select name="accountId" required><option value="">Select professional</option>${people.map(x=>`<option value="${esc(x.id)}">${esc(x.name)} · ${esc(x.registrationNumber)}</option>`).join('')}</select></label><p class="assignment-mode muted" aria-live="polite">Select an account to add or update its review round.</p>${people.length?'':`<p class="muted">No approved ${esc(J.roleDefinitions[role].label)} is available. Administration must approve a submitted role profile first.</p>`}<div class="workflow-checks"><fieldset><legend>Share selected property fields</legend>${possible.map(([k])=>`<label><input type="checkbox" name="fieldIds" value="${esc(k)}"> ${esc(fieldLabel(k))}</label>`).join('')}</fieldset><fieldset><legend>Share selected documents</legend>${(r.documents||[]).map(x=>`<label><input type="checkbox" name="documentIds" value="${esc(x.id)}"> ${esc(x.name)}</label>`).join('')||'<p>No submitted documents.</p>'}</fieldset></div><div class="workflow-checks"><fieldset><legend>Share submitted report text</legend><p class="muted">Only report text is shown. Identity and attachments stay hidden; review free text for personal details before sharing.</p>${reportChoices.map(x=>`<div class="report-share-option"><strong>${esc(x.label)}</strong>${J.reportFields[x.role].filter(key=>x.report[key]).map(key=>`<label><input class="report-share-field" type="checkbox" data-report-id="${esc(x.id)}" data-field-id="${esc(key)}"> ${esc(key.replace(/([A-Z])/g,' $1').replace(/^./,c=>c.toUpperCase()))}</label>`).join('')}${x.report.attachment?`<label><input class="report-share-attachment" type="checkbox" data-report-id="${esc(x.id)}"> Include attachment: ${esc(x.report.attachment.name)}</label>`:''}</div>`).join('')||'<p>No submitted reports yet.</p>'}</fieldset><fieldset><legend>Share internal team notes</legend><p class="muted">Only selected note text is shown; staff identity stays hidden.</p>${(r.internalRemarks||[]).map((x,i)=>`<label><input type="checkbox" name="remarkIndexes" value="${i}"> ${esc(x.text)}</label>`).join('')||'<p>No internal notes yet.</p>'}</fieldset></div>${textarea('taskNote','Review task / context','',{max:500})}<button class="button" type="submit">Save assignment</button></form>`:''}</div></section>`}).join('')}<section class="card"><div class="card-body"><h2>Property activity trail</h2><p>Actions are shown in the order they happened, including Owner form stages, requests, assignments, reports and status changes.</p><ol class="property-audit-timeline">${(r.auditTrail||[]).map(x=>`<li><span class="property-audit-dot" aria-hidden="true"></span><div class="property-audit-entry"><div class="property-audit-heading"><strong>${esc(x.type==='step_completed'?x.details.step+' step completed':x.type.replaceAll('_',' '))}</strong><time>${date(x.at)}</time></div><small>${esc(x.actorRole)} · ${esc(x.actorId)}</small>${x.type==='step_completed'?'':`<p>${esc(Object.entries(x.details||{}).map(([k,v])=>`${k}: ${auditValue(v)}`).join(' · '))}</p>`}</div></li>`).join('')||'<li>No recorded actions.</li>'}</ol></div></section>`}
function auditValue(value){if(Array.isArray(value))return value.map(auditValue).join(', ');if(value&&typeof value==='object')return Object.entries(value).map(([key,item])=>`${key}: ${auditValue(item)}`).join(', ');return String(value??'')}
function enquiryAuditCard(r){const events=r.auditTrail||[];return `<section class="card"><div class="card-body"><h2>Enquiry activity trail</h2><p>Buyer submission, team actions, information requests and responses, and status changes appear in time order.</p><ol class="property-audit-timeline">${events.map(x=>`<li><span class="property-audit-dot" aria-hidden="true"></span><div class="property-audit-entry"><div class="property-audit-heading"><strong>${esc(x.type.replaceAll('_',' '))}</strong><time>${date(x.at)}</time></div><small>${esc(x.actorRole==='legacy'?'Earlier record · actor '+x.actorId:x.actorRole+' · '+x.actorId)}</small><p>${esc(Object.entries(x.details||{}).filter(([k])=>k!=='imported').map(([k,v])=>`${k}: ${auditValue(v)}`).join(' · '))}</p></div></li>`).join('')||'<li>No activity recorded.</li>'}</ol></div></section>`}
function enquiryCasePage(r,team,subs,employees){const tab=['details','actions','market','activity'].includes(state.params.get('tab'))?state.params.get('tab'):'details',base='#request?kind=enquiry&id='+encodeURIComponent(r.id),labels={details:'Enquiry details',actions:'Actions & requests',market:'Market support',activity:'Activity trail'};const contact=r.contact?`<dt>Buyer contact</dt><dd>${esc(r.contact.name)} · ${esc(r.contact.mobile)} · ${esc(r.contact.email||'No email')}</dd>`:'';const details=`<section class="card detail-card"><div class="card-body"><h2>Buyer interest</h2><dl class="detail-list"><dt>Enquiry</dt><dd>${esc(r.id)}</dd><dt>Status</dt><dd>${esc(r.status.replaceAll('_',' '))}</dd><dt>Property</dt><dd>${esc([r.preview?.id||r.propertyId,r.preview?.category,r.preview?.location].filter(Boolean).join(' · '))}</dd><dt>Interest</dt><dd>${esc(r.interestType)} · ${esc(r.requirement||'No requirement')} · ${esc(r.range||'No range')}</dd><dt>Buyer message</dt><dd>${esc(r.message)}</dd>${contact}<dt>Sub Admin</dt><dd>${esc(team.find(x=>x.id===r.subAdminId)?.name||r.subAdminId||'Unassigned')}</dd><dt>Employee</dt><dd>${esc(team.find(x=>x.id===r.employeeId)?.name||r.employeeId||'Unassigned')}</dd></dl></div></section>`;const actions=`<section class="card detail-card"><div class="card-body"><h2>Process enquiry</h2><form id="request-form" data-kind="enquiry" data-id="${esc(r.id)}">${formError()}${current().role==='superadmin'?select('subAdminId','Assign Sub Admin',r.subAdminId||'',[['','Unassigned'],...subs.map(x=>[x.id,x.name])]):''}${current().role!=='employee'?select('employeeId','Assign Employee',r.employeeId||'',[['','Unassigned'],...employees.map(x=>[x.id,x.name])]):''}${select('status','Processing status',r.status,['submitted','assigned','in_discussion','additional_info','closed'].map(x=>[x,x.replaceAll('_',' ')]))}${textarea('remark','Internal remark','',{max:1200})}${textarea('followUp','Follow-up activity','',{max:500})}${textarea('request','Request additional information','',{max:500})}${textarea('update','Customer-visible update','',{max:500})}<button class="button" type="submit">Save request changes</button></form></div></section>`;const history=`<section class="card"><div class="card-body"><h2>Internal history</h2>${[['Assignments',r.assignmentHistory],['Status changes',r.statusHistory],['Internal remarks',r.internalRemarks],['Follow-ups',r.followUps],['Information requests',r.requests]].map(([label,rows])=>`<h3>${label}</h3><ul>${(rows||[]).map(x=>`<li>${esc(x.text||x.message||x.status||[x.subAdminId,x.employeeId].filter(Boolean).join(' → ')||'Updated')} · ${date(x.at||x.createdAt)}</li>`).join('')||'<li>None yet</li>'}</ul>`).join('')}</div></section>`;const market=`<section class="card"><div class="card-body"><h2>Broker / NV Partner market support</h2><p>Assign only approved market-support accounts. Buyer and Owner contact details are not shared.</p>${['broker','partner'].map(role=>{const tasks=[...(r.marketTasks?.[role]?[r.marketTasks[role]]:[]),...(r.marketTasksExtra?.[role]||[])],people=['employee','superadmin'].includes(current().role)?J.approvedProfessionals(current(),role).filter(x=>x.id!==r.buyerId):[];return `<div class="market-support-block"><h3>${esc(J.roleDefinitions[role].label)}</h3>${tasks.length?tasks.map((task,index)=>`<div class="assigned-review"><h4>Round ${esc(task.round||1)}: ${esc(people.find(x=>x.id===task.accountId)?.name||task.accountId)} · ${esc(task.status)}</h4>${task.followUpTo?'<p class="muted">Follow-up request; earlier update retained.</p>':''}<p>Shared: ${esc(task.fieldIds.join(', '))}</p>${task.update?`<p><strong>Update:</strong> ${esc(task.update.notes)}</p><p><strong>Next action:</strong> ${esc(task.update.nextAction||'—')}</p>`:''}</div>`).join(''):'<p>Not assigned.</p>'}${['employee','superadmin'].includes(current().role)?`<form class="market-assignment-form" data-id="${esc(r.id)}" data-role="${role}">${formError()}<label>Approved account<select name="accountId" required><option value="">Select account</option>${people.map(x=>`<option value="${esc(x.id)}">${esc(x.name)}</option>`).join('')}</select></label><p class="assignment-mode muted" aria-live="polite">Select an account to add or update its enquiry review round.</p><fieldset class="market-fieldset"><legend>Share selected enquiry details</legend>${[['propertyId','Property reference'],['category','Property category'],['location','Location'],['state','State'],['interestType','Interest type'],['requirement','Buyer requirement'],['range','Investment range']].map(([key,label])=>`<label><input type="checkbox" name="fieldIds" value="${key}" ${['propertyId','category','location'].includes(key)?'checked':''}> ${label}</label>`).join('')}</fieldset>${textarea('taskNote','Task instructions','',{max:500})}<button class="button" type="submit">Save assignment</button></form>`:''}</div>`}).join('')}</div></section>`;const panels={details,actions,market,activity:enquiryAuditCard(r)+history};return heading('REQUEST WORKFLOWS',r.id,'Review the enquiry, take action, and follow its history.',link('Back to queue','#requests?kind=enquiry','button secondary'))+`<nav class="property-case-tabs" aria-label="Enquiry sections">${Object.entries(labels).map(([key,label])=>`<a href="${base}&tab=${key}" ${key===tab?'aria-current="page"':''}>${label}</a>`).join('')}</nav><div class="property-case-panel">${panels[tab]}</div>`}
function requestDetail(){const kind=state.params.get('kind')==='enquiry'?'enquiry':'property',r=J.adminDetail(current(),kind,state.params.get('id')),team=current().role==='superadmin'||current().role==='subadmin'?S.listUsers():[],subs=team.filter(x=>x.role==='subadmin'&&x.active),employees=team.filter(x=>x.role==='employee'&&x.active&&(current().role==='superadmin'?!r.subAdminId||x.managerId===r.subAdminId:x.managerId===current().id));return kind==='property'?propertyCasePage(r,team,subs,employees):enquiryCasePage(r,team,subs,employees)}
const customerRole=role=>J.roleDefinitions[role]?.label||role;
function contactInboxPage(){
 const status=C.statuses.includes(state.params.get('status'))?state.params.get('status'):'all';
 const all=C.list(),rows=all.filter(item=>status==='all'||item.status===status);
 const labels={new:'New',in_progress:'In progress',closed:'Closed'};
 return heading('WEBSITE ENQUIRIES','Contact enquiries','Messages submitted through the public Contact Us form in this browser.')+
 `<nav class="property-case-tabs" aria-label="Contact enquiry status">${[['all','All'],...Object.entries(labels)].map(([value,label])=>`<a href="#contacts?status=${value}" ${status===value?'aria-current="page"':''}>${label} (${value==='all'?all.length:all.filter(item=>item.status===value).length})</a>`).join('')}</nav>`+
 `<section class="card"><div class="table-wrap"><table class="data-table"><thead><tr><th>Reference</th><th>Contact</th><th>Topic</th><th>Received</th><th>Status</th><th>Action</th></tr></thead><tbody>${rows.map(item=>`<tr><td><strong>${esc(item.id)}</strong></td><td>${esc(item.name)}<br><small>${esc(item.mobile||item.phone||'No mobile')} · ${esc(item.email||'No email')}</small></td><td>${esc(item.topic)}</td><td>${dateTime(item.submittedAt)}</td><td>${badge(item.status!=='closed',labels[item.status]||item.status)}</td><td>${link('View','#contact-enquiry?id='+encodeURIComponent(item.id),'button ghost small')}</td></tr>`).join('')}</tbody></table></div>${rows.length?'':empty('No contact enquiries',status==='all'?'Submitted website enquiries will appear here.':'No enquiries match this status.')}</section>`;
}
function contactEnquiryPage(){
 const item=C.get(state.params.get('id'));if(!item)throw Error('Contact enquiry not found.');
 const labels={new:'New',in_progress:'In progress',closed:'Closed'};
 return heading('WEBSITE ENQUIRIES',item.id,'Contact form submission and team follow-up status.',link('Back to contact enquiries','#contacts','button secondary'))+
 `<div class="detail-grid"><section class="card detail-card"><div class="card-body"><h2>Enquiry details</h2><dl class="detail-list"><dt>Received</dt><dd>${dateTime(item.submittedAt)}</dd><dt>Name</dt><dd>${esc(item.name)}</dd><dt>Mobile</dt><dd>${esc(item.mobile||item.phone||'Not supplied')}</dd><dt>Email</dt><dd>${esc(item.email||'Not supplied')}</dd><dt>Topic</dt><dd>${esc(item.topic)}</dd><dt>Status</dt><dd>${badge(item.status!=='closed',labels[item.status]||item.status)}</dd></dl><h3>Message</h3><p class="contact-message">${esc(item.message)}</p></div></section>`+
 `<section class="card detail-card"><div class="card-body"><h2>Team follow-up</h2><form id="contact-status-form" data-id="${esc(item.id)}">${formError()}${select('status','Status',item.status,Object.entries(labels))}<button class="button" type="submit">Save status</button></form><h3>Activity</h3><ol class="contact-history">${(item.history||[]).map(event=>`<li><strong>${event.type==='submitted'?'Enquiry submitted':'Status changed to '+(labels[event.status]||event.status)}</strong><span>${dateTime(event.at)}${event.actorRole?' · '+esc(event.actorRole):''}</span></li>`).join('')}</ol></div></section></div>`;
}
function customersPage(){if(current().role!=='superadmin')throw Error('Customer accounts require Super Admin access.');const role=state.params.get('role')||'all',review=state.params.get('review')||'all';return heading('CUSTOMER ACCOUNTS','Customers and their roles','Filter by customer role and professional review status while keeping join history visible.',link('Create NV Channel Partner','#partner-create','button'))+`<section class="card"><div class="toolbar customer-filters"><label class="search-box">${icon('search')}<input type="search" id="customer-search" placeholder="Search name, mobile or credentials" aria-label="Search customers" value="${esc(state.customerQuery||'')}"></label><div class="filters"><label class="sr-only" for="customer-role-filter">Customer role</label><select id="customer-role-filter" aria-label="Customer role"><option value="all" ${role==='all'?'selected':''}>All customers</option><option value="owner" ${role==='owner'?'selected':''}>Property Owners</option><option value="buyer" ${role==='buyer'?'selected':''}>Buyers / Investors</option><option value="lawyer" ${role==='lawyer'?'selected':''}>Lawyers</option><option value="ca" ${role==='ca'?'selected':''}>Chartered Accountants</option><option value="broker" ${role==='broker'?'selected':''}>Brokers</option><option value="arbitrator" ${role==='arbitrator'?'selected':''}>Arbitrators</option><option value="builder" ${role==='builder'?'selected':''}>Builders / Developers</option><option value="partner" ${role==='partner'?'selected':''}>NV Channel Partners</option></select><label class="sr-only" for="customer-review-filter">Professional review status</label><select id="customer-review-filter" aria-label="Professional review status" ${['owner','buyer','partner'].includes(role)?'disabled':''}><option value="all" ${review==='all'?'selected':''}>All review statuses</option><option value="submitted" ${review==='submitted'?'selected':''}>Awaiting review</option><option value="approved" ${review==='approved'?'selected':''}>Approved</option><option value="rejected" ${review==='rejected'?'selected':''}>Returned for changes</option></select><button class="button ghost small" type="button" data-action="reset-customer-filters">Reset</button></div></div><div id="customer-results"></div></section>`}
function paintCustomers(){const container=$('#customer-results');if(!container)return;const role=state.params.get('role')||'all',review=state.params.get('review')||'all',query=(state.customerQuery||'').trim().toLowerCase();const rows=J.listCustomers(current()).filter(u=>{const roles=u.roleHistory.map(x=>x.role),profiles=u.professionalProfiles||{},selected=role==='all'?Object.values(profiles):[profiles[role]];return (role==='all'||roles.includes(role))&&(review==='all'||selected.some(p=>p?.status===review))&&(!query||[u.name,u.mobile,u.email,...roles.map(customerRole),...Object.values(profiles).map(p=>p.registrationNumber)].join(' ').toLowerCase().includes(query))});container.innerHTML=`<p class="customer-count">${rows.length} ${rows.length===1?'customer':'customers'} shown</p>${rows.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Customer</th><th>Joined as</th><th>Added roles</th><th>Basic KYC</th><th>Professional review</th><th></th></tr></thead><tbody>${rows.map(u=>`<tr><td><strong>${esc(u.name||'Profile pending')}</strong>${u.demo?' <span class="pill blue">Demo</span>':''}<br><small>${esc(u.mobile)} · ${esc(u.email||'No email')}</small></td><td>${esc(customerRole(u.primaryRole)||'Pending')}</td><td>${esc(u.roleHistory.filter(x=>x.role!==u.primaryRole).map(x=>customerRole(x.role)).join(', ')||'None')}</td><td>${badge(u.basicKyc.status==='complete',u.basicKyc.status)}</td><td>${Object.entries(u.professionalProfiles).map(([r,p])=>`${esc(customerRole(r))}: ${esc(p.status)}`).join('<br>')||'—'}</td><td>${link('Review','#customer?id='+encodeURIComponent(u.id),'button ghost small')}</td></tr>`).join('')}</tbody></table></div>`:empty('No matching customers','Try another role, status or search term.')}`}
function customerPage(){if(current().role!=='superadmin')throw Error('Customer accounts require Super Admin access.');const u=J.listCustomers(current()).find(x=>x.id===state.params.get('id'));if(!u)throw Error('Customer not found.');return heading('CUSTOMER ACCOUNTS',u.name||'Profile pending','Review role history and professional credentials.',link('Back to customers','#customers','button secondary'))+`${u.roleHistory.some(x=>x.role==='partner')?'':`<section class="card detail-card"><div class="card-body"><h2>NV Channel Partner</h2><p>Assign this admin-controlled role to this existing account. Basic KYC must already be complete.</p>${u.basicKyc.status==='complete'?`<form id="partner-existing-form" data-mobile="${esc(u.mobile)}">${formError()}<button class="button" type="submit">Activate NV Channel Partner</button></form>`:link('Complete KYC when creating partner','#partner-create','button secondary')}</div></section>`}<section class="card detail-card"><div class="card-body"><h2>Account</h2><dl class="detail-list"><dt>Mobile</dt><dd>${esc(u.mobile)}</dd><dt>Email</dt><dd>${esc(u.email||'Not provided')}</dd><dt>Joined as</dt><dd>${esc(customerRole(u.primaryRole)||'Pending')} · ${date(u.createdAt)}</dd><dt>Basic KYC</dt><dd>${esc(u.basicKyc.status)}${u.basicKyc.status==='complete'?` · Aadhaar •••• ${esc(u.basicKyc.aadhaarLast4)} · PAN ${esc(u.basicKyc.panMasked)}`:''}</dd></dl><h3>Role history</h3><ul>${u.roleHistory.map((entry,i)=>`<li>${esc(customerRole(entry.role))} · ${i===0?'Joined':'Added'} ${date(entry.joinedAt)}</li>`).join('')}</ul></div></section><div class="user-grid">${Object.entries(u.professionalProfiles).map(([role,p])=>`<section class="card detail-card"><div class="card-body"><h2>${esc(customerRole(role))}</h2><p>Status: ${badge(p.status==='approved',p.status)}</p><dl class="detail-list"><dt>Registration</dt><dd>${esc(p.registrationNumber)}</dd><dt>Authority</dt><dd>${esc(p.authority)}</dd><dt>Qualification</dt><dd>${esc(p.qualification||'Not provided')}</dd><dt>Credential documents</dt><dd>${esc(p.enrolmentDocument)}<br>${esc(p.practiceDocument)}</dd><dt>Submitted</dt><dd>${date(p.submittedAt)}</dd>${p.review?`<dt>Last review</dt><dd>${esc(p.review.reason||p.status)} · ${date(p.review.at)}</dd>`:''}</dl>${p.status==='submitted'?`<form id="professional-review-form" data-id="${esc(u.id)}" data-role="${esc(role)}">${formError()}${textarea('reason','Reason (required for rejection)','',{max:500})}<div class="form-actions"><button class="button" type="submit" value="approved">Approve</button><button class="button secondary" type="submit" value="rejected">Return for changes</button></div></form>`:''}</div></section>`).join('')||'<section class="card"><div class="card-body"><h2>No professional submissions</h2><p>Professional and organisation profiles appear here after submission.</p></div></section>'}</div>`}
function partnerCreatePage(){if(current().role!=='superadmin')throw Error('Super Admin access required.');return heading('CUSTOMER ACCOUNTS','Create NV Channel Partner','Use an existing mobile number to add the role, or create a new account. Existing profile and basic KYC are reused.',link('Back to customers','#customers','button secondary'))+`<section class="card detail-card"><div class="card-body"><form id="partner-create-form">${formError()}${field('mobile','Mobile number','',{required:true})}${field('name','Name for a new account','')}${field('email','Email for a new account','',{type:'email'})}<p>For an existing account with completed basic KYC, leave the identity fields blank. Otherwise enter Aadhaar and PAN to complete basic KYC.</p>${field('aadhaar','Aadhaar number','')}${field('pan','PAN number','')}<button class="button" type="submit">Activate NV Channel Partner</button></form></div></section>`}const views={'partner-create':partnerCreatePage,'prototype-summary':prototypeSummary,contacts:contactInboxPage,'contact-enquiry':contactEnquiryPage,customers:customersPage,customer:customerPage,requests:requestPage,request:requestDetail,overview,users:usersPage,user:userDetails,'user-edit':userForm,permissions:permissionsPage,masters:mastersPage,'master-edit':masterForm,plans:plansPage,plan:planDetails,'plan-edit':planForm,cms:cmsPage,'cms-edit':cmsEditor,'cms-preview':cmsPreview,profile,'profile-edit':profileEdit,password:passwordPage};
function render(){
 state.dirty=false;savedSelection=null;
 if(!current()){loginView();return;}
 let page=state.page;if(!Object.hasOwn(views,page))page='overview';
 try{if(['customers','customer','partner-create'].includes(page)&&current().role!=='superadmin')throw Error('Customer accounts require Super Admin access.');if(['users','user','user-edit','permissions'].includes(page)&&!S.can('users','view'))throw Error('User management is outside your assigned permissions.');shell(views[page]());if(page==='users')paintUsers();if(page==='customers')paintCustomers();if(page==='masters')paintMasters();if(page==='plans')paintPlans();if(page==='cms-edit')updateEditorCount();const activeInput=$('#field-active');const recordId=state.params.get('id');const resource=page==='user-edit'?'users':page==='master-edit'?masterKind():page==='plan-edit'?'subscriptions':null;if(activeInput&&recordId&&resource&&!S.can(resource,'status'))activeInput.disabled=true;if(page==='user-edit'&&state.params.get('focus')==='manager')$('#field-managerId')?.focus();}
 catch(error){if(!current()){loginView(error.message);return;}shell(heading('ACCESS & AVAILABILITY','This page isn’t available.',error.message,link('Back to overview','#overview','button','grid')));}
 document.title=`Nirvivad — ${pageLabels[page]||'Administration'}`;
 closeMenu();
}
function route(){lastHash=location.hash;const raw=location.hash.slice(1);if(raw==='main'){$('#main')?.focus();return;}const [page,query='']=raw.split('?');state={...state,page:page||'overview',params:new URLSearchParams(query),query:'',role:'all',status:'all',manager:'all',tablePage:1};if($('#admin-dialog').open)$('#admin-dialog').close();render();window.scrollTo({top:0,behavior:'instant'});}
function go(href){state.dirty=false;if(location.hash===href){route();}else location.hash=href;}
function refreshList(){if(state.page==='customers')paintCustomers();if(state.page==='users')paintUsers();if(state.page==='masters')paintMasters();if(state.page==='plans')paintPlans();}
function getFormData(form){return Object.fromEntries(new FormData(form));}
function reportSharesFromForm(form){const shares=new Map();for(const box of $$('.report-share-field:checked,.report-share-attachment:checked',form)){const reportId=box.dataset.reportId;if(!shares.has(reportId))shares.set(reportId,{reportId,fieldIds:[],includeAttachment:false});const share=shares.get(reportId);if(box.classList.contains('report-share-attachment'))share.includeAttachment=true;else share.fieldIds.push(box.dataset.fieldId)}return [...shares.values()]}

async function handleSubmit(event){const form=event.target;if(!form.id?.endsWith('-form')&&!form.classList.contains('professional-assignment-form')&&!form.classList.contains('market-assignment-form'))return;event.preventDefault();const submitter=event.submitter;const controls=$$('button[type=submit]',form);controls.forEach(b=>b.disabled=true);const error=form.querySelector('.error-message');if(error)error.hidden=true;
 try{
 const d=getFormData(form);let result;
 if(form.id==='login-form'){await S.login(d.email,d.password);state.dirty=false;go('#overview');toast('Welcome to your Administration workspace.');}
 if(form.id==='partner-create-form'||form.id==='partner-existing-form'){const partner=J.activatePartner(current(),form.id==='partner-existing-form'?{mobile:form.dataset.mobile}:d);go('#customer?id='+encodeURIComponent(partner.id));toast('NV Channel Partner activated.');}
 if(form.id==='professional-review-form'){J.reviewProfessional(current(),form.dataset.id,form.dataset.role,submitter.value,d.reason);go('#customer?id='+encodeURIComponent(form.dataset.id));toast('Professional review saved.');}
 if(form.id==='property-items-form'){J.requestPropertyItems(current(),form.dataset.id,{fieldIds:$$('input[name=fieldIds]:checked',form).map(x=>x.value),documentTypeIds:$$('input[name=documentTypeIds]:checked',form).map(x=>x.value),message:d.message});go('#request?kind=property&id='+encodeURIComponent(form.dataset.id)+'&tab=actions');toast('Information request sent.');}
 if(form.classList.contains('market-assignment-form')){J.assignMarketEnquiry(current(),form.dataset.id,form.dataset.role,d.accountId,{fieldIds:$$('input[name=fieldIds]:checked',form).map(x=>x.value),taskNote:d.taskNote});go('#request?kind=enquiry&id='+encodeURIComponent(form.dataset.id)+'&tab=market');toast('Market-support assignment saved.');}
 if(form.classList.contains('professional-assignment-form')){J.assignProfessional(current(),form.dataset.id,form.dataset.role,d.accountId,{fieldIds:$$('input[name=fieldIds]:checked',form).map(x=>x.value),documentIds:$$('input[name=documentIds]:checked',form).map(x=>x.value),reportShares:reportSharesFromForm(form),remarkIndexes:$$('input[name=remarkIndexes]:checked',form).map(x=>x.value),taskNote:d.taskNote});go('#request?kind=property&id='+encodeURIComponent(form.dataset.id)+'&tab=professionals');toast('Review assignment saved.');}
 if(form.id==='contact-status-form'){C.updateStatus(form.dataset.id,d.status,current());go('#contact-enquiry?id='+encodeURIComponent(form.dataset.id));toast('Contact enquiry status updated.');}
 if(form.id==='request-form'){const input={status:d.status,remark:d.remark,followUp:d.followUp,request:d.request,update:d.update};if(current().role==='superadmin')input.subAdminId=d.subAdminId;if(current().role!=='employee')input.employeeId=d.employeeId;J.adminUpdate(current(),form.dataset.kind,form.dataset.id,input,current().role==='employee'?[]:S.listUsers());go('#request?kind='+form.dataset.kind+'&id='+encodeURIComponent(form.dataset.id)+'&tab=actions');toast('Request updated.');}
 if(form.id==='user-form'){
  const limited=current().role!=='superadmin';const role=limited?'employee':d.role;result=await S.saveUser({name:d.name,email:d.email,phone:d.phone,designation:d.designation,department:d.department,role,managerId:limited?current().id:d.managerId,alsoEmployee:role==='subadmin'&&!!d.alsoEmployee,active:form.elements.active.checked,...(!form.dataset.id?{password:d.password}:{})},form.dataset.id||null);go('#user?id='+encodeURIComponent(result.id));toast(form.dataset.id?'User updated.':'User created.');
 }
 if(form.id==='permissions-form'){const overrides={};for(const [key,value] of Object.entries(d)){if(!key.startsWith('perm:')||value==='inherit')continue;const [,resource,action]=key.split(':');overrides[resource]||={};overrides[resource][action]=value==='allow';}S.savePermissions(form.dataset.id,overrides);go('#user?id='+encodeURIComponent(form.dataset.id));toast('Permissions updated.');}
 if(form.id==='master-form'){result=S.saveMaster(form.dataset.kind,{name:d.name,code:d.code,description:d.description,sortOrder:Number(d.sortOrder),symbol:d.symbol||'',requiresDetails:!!d.requiresDetails,active:form.elements.active.checked},form.dataset.id||null);go('#masters?kind='+form.dataset.kind);toast('Master entry saved.');}
 if(form.id==='plan-form'){const features=Object.fromEntries(Object.keys(S.planFeatures).map(k=>[k,d['feature-'+k]||'']));result=S.savePlan({name:d.name,code:d.code,description:d.description,durationMonths:Number(d.durationMonths),propertyLimit:Number(d.propertyLimit),price:d.price===''?null:Number(d.price),currency:'INR',active:form.elements.active.checked,features},form.dataset.id||null);go('#plan?id='+encodeURIComponent(result.id));toast('Subscription plan saved.');}
 if(form.id==='profile-form'){S.updateProfile({name:d.name,email:d.email,phone:d.phone,department:d.department,designation:d.designation});go('#profile');toast('Profile updated.');}
 if(form.id==='password-form'){await S.changePassword(d.currentPassword,d.newPassword,d.confirmPassword);S.logout();state.dirty=false;loginView();toast('Password changed. Sign in with your new password.');}
 if(form.id==='cms-form'){const content=$('#cms-editor').innerHTML;const status=submitter?.value==='published'?'published':'draft';S.saveCms(form.dataset.slug,{title:d.title,content,status});go('#cms');toast(status==='published'?'Policy page published.':'Draft saved. The last published page remains available.');}
 }catch(err){if(error){error.textContent=err.message||String(err);error.hidden=false;error.focus()}else report(err);}finally{controls.forEach(b=>b.disabled=false);}
}
function restoreEditorSelection(){const editor=$('#cms-editor');if(!editor)return;editor.focus();if(savedSelection&&editor.contains(savedSelection.commonAncestorContainer)){const selection=window.getSelection();selection.removeAllRanges();selection.addRange(savedSelection);}}
function updateEditorCount(){const editor=$('#cms-editor');if(editor&&$('#editor-count'))$('#editor-count').textContent=editor.textContent.trim().length.toLocaleString('en-IN');}
async function actionClick(event){const el=event.target.closest('button,a');if(!el)return;
 if(el.tagName==='A'&&el.getAttribute('href')?.startsWith('#')&&state.dirty){event.preventDefault();const href=el.getAttribute('href');confirmAction('Leave without saving?','Your unsaved changes will be discarded.',()=>go(href));return;}
 if(el.dataset.command){restoreEditorSelection();document.execCommand(el.dataset.command,false,null);state.dirty=true;updateEditorCount();return;}
 const action=el.dataset.action;if(!action)return;
 try{
 if(action==='menu'){const open=!document.body.classList.contains('sidebar-open');document.body.classList.toggle('sidebar-open',open);$('#nav-shade').hidden=!open;el.setAttribute('aria-expanded',String(open));}
 if(action==='logout'){const leave=()=>{S.logout();state.dirty=false;loginView();toast('You have signed out.');};if(state.dirty)confirmAction('Sign out without saving?','Unsaved changes will be discarded.',leave);else leave();}
 if(action==='fill-demo'){$('#field-email').value=el.dataset.email;$('#field-password').value='Nirvivad@123';$('#field-email').focus();}
 if(action==='toggle-password'){const f=document.getElementById(el.dataset.for);f.type=f.type==='password'?'text':'password';el.setAttribute('aria-label',f.type==='password'?'Show password':'Hide password');}
 if(action==='close-dialog'){$('#admin-dialog').close();confirmation=null;}
 if(action==='confirm'){const fn=confirmation;confirmation=null;$('#admin-dialog').close();await fn?.();}
 if(action==='user-tab'){state.params.set('view',el.dataset.view);go('#users?view='+el.dataset.view);}
 if(action==='reset-customer-filters'){state.customerQuery='';go('#customers?role=all&review=all');}
 if(action==='reset-filters'){state.query='';state.role='all';state.status='all';state.tablePage=1;render();}
 if(action==='page-prev'||action==='page-next'){state.tablePage+=action==='page-next'?1:-1;refreshList();}
 if(action==='reset-permissions'){$$('select[name^="perm:"]').forEach(s=>s.value='inherit');state.dirty=true;}
 if(action==='user-status'){const u=S.getUser(el.dataset.id);confirmAction(u.active?'Deactivate account?':'Activate account?',`${u.name} ${u.active?'will no longer be able to sign in.':'will be able to sign in again.'} Managers with direct reports cannot be deactivated until reassignment.`,()=>{S.setUserStatus(u.id,!u.active);render();toast('Account status updated.');});}
 if(action==='user-delete'){const u=S.getUser(el.dataset.id);confirmAction('Delete this user?',`Delete ${u.name} from this prototype? This cannot be undone. Managers must have no direct reports.`,()=>{S.deleteUser(u.id);go('#users');toast('User deleted.');},true);}
 if(action==='master-view'){const m=S.listMaster(el.dataset.kind).find(x=>x.id===el.dataset.id);if(!m)throw Error('Entry not found.');dialog(m.name,`<dl class="detail-list"><dt>Code</dt><dd>${esc(m.code)}</dd><dt>Description</dt><dd>${esc(m.description||'Not supplied')}</dd><dt>Display order</dt><dd>${m.sortOrder||0}</dd><dt>Status</dt><dd>${badge(m.active)}</dd><dt>Additional details</dt><dd>${m.requiresDetails?'Required when selected':'Not required'}</dd>${el.dataset.kind==='unit'?`<dt>Symbol</dt><dd>${esc(m.symbol||'Not set')}</dd>`:''}</dl>`,button('Close','close-dialog'));}
 if(action==='master-status'||action==='master-delete'){const k=el.dataset.kind;const m=S.listMaster(k).find(x=>x.id===el.dataset.id);if(!m)throw Error('Entry not found.');const deleting=action==='master-delete';confirmAction(deleting?'Delete master entry?':m.active?'Deactivate entry?':'Activate entry?',deleting?`Permanently delete “${m.name}” from this prototype?`:`Change the availability of “${m.name}”?`,()=>{if(deleting)S.deleteMaster(k,m.id);else S.setMasterStatus(k,m.id,!m.active);render();toast(deleting?'Entry deleted.':'Entry status updated.');},deleting);}
 if(action==='plan-status'||action==='plan-delete'){const p=S.listPlans().find(x=>x.id===el.dataset.id);if(!p)throw Error('Plan not found.');const deleting=action==='plan-delete';confirmAction(deleting?'Delete subscription plan?':p.active?'Deactivate plan?':'Activate plan?',deleting?`Permanently delete ${p.name} from this prototype?`:`${p.active?'Deactivate':'Activate'} ${p.name}? An active plan requires configured pricing.`,()=>{if(deleting){S.deletePlan(p.id);go('#plans');}else{S.setPlanStatus(p.id,!p.active);render();}toast(deleting?'Plan deleted.':'Plan status updated.');},deleting);}
 if(action==='cms-preview-draft'){dialog($('#field-title').value||'Policy preview',`<article class="prose">${S.sanitizeHtml($('#cms-editor').innerHTML)}</article>`,button('Continue editing','close-dialog'));}
 if(action==='editor-link'){const url=$('#editor-link').value.trim();if(!/^https?:\/\//i.test(url))throw Error('Enter a link beginning with https:// or http://.');const parsed=new URL(url);if(!['https:','http:'].includes(parsed.protocol))throw Error('This link type is not allowed.');restoreEditorSelection();document.execCommand('createLink',false,parsed.href);state.dirty=true;$('#editor-link').value='';}
 }catch(err){report(err);}
}
document.addEventListener('click',actionClick);
document.addEventListener('submit',handleSubmit);
document.addEventListener('input',event=>{if(event.target.id==='customer-search'){state.customerQuery=event.target.value;paintCustomers();return;}if(event.target.id==='list-search'){state.query=event.target.value;state.tablePage=1;refreshList();return;}if(event.target.closest('form')&&event.target.closest('form').id!=='login-form')state.dirty=true;if(event.target.id==='cms-editor'){state.dirty=true;updateEditorCount();}});
document.addEventListener('change',event=>{
 if(event.target.name==='accountId'&&event.target.closest('.professional-assignment-form,.market-assignment-form')){const form=event.target.form,kind=form.classList.contains('market-assignment-form')?'enquiry':'property',record=J.adminDetail(current(),kind,form.dataset.id),role=form.dataset.role,taskSet=kind==='property'?'professionalTasks':'marketTasks',latest=[...(record[taskSet]?.[role]?[record[taskSet][role]]:[]),...(record[taskSet+'Extra']?.[role]||[])].filter(x=>x.accountId===event.target.value).at(-1),task=latest?.status==='reported'?null:latest;const mode=form.querySelector('.assignment-mode');if(mode)mode.textContent=latest?.status==='reported'?'Previous submission stays read-only. Saving creates a new follow-up round.':task?'Editing the open round. Its report has not been submitted yet.':'Saving creates a first assignment round.';for(const name of ['fieldIds','documentIds','reportIds','remarkIndexes'])$$(`input[name="${name}"]`,form).forEach(box=>box.checked=task?!!task[name]?.includes(box.value):kind==='enquiry'&&name==='fieldIds'&&['propertyId','category','location'].includes(box.value));if(form.elements.taskNote)form.elements.taskNote.value=task?.taskNote||'';const shares=task?.reportShares||[];$$('.report-share-field,.report-share-attachment',form).forEach(box=>{const share=shares.find(x=>x.reportId===box.dataset.reportId);box.checked=box.classList.contains('report-share-attachment')?!!share?.includeAttachment:!!share?.fieldIds?.includes(box.dataset.fieldId)||!task?.reportShares&&!!task?.reportIds?.includes(box.dataset.reportId)});return;}
 if(event.target.id==='customer-role-filter'||event.target.id==='customer-review-filter'){const role=event.target.id==='customer-role-filter'?event.target.value:$('#customer-role-filter').value;const review=['owner','buyer','partner'].includes(role)?'all':event.target.id==='customer-review-filter'?event.target.value:$('#customer-review-filter').value;go('#customers?role='+encodeURIComponent(role)+'&review='+encodeURIComponent(review));return;}
 if(event.target.id==='filter-role')state.role=event.target.value;if(event.target.id==='filter-status')state.status=event.target.value;if(event.target.id.startsWith('filter-')){state.tablePage=1;refreshList();}
 if(event.target.closest('form')&&event.target.closest('form').id!=='login-form')state.dirty=true;
 if(event.target.id==='field-role'&&$('#user-form')){const role=event.target.value;const id=$('#user-form').dataset.id;const options=managerOptions(role,id||null);$('#field-managerId').innerHTML=options.map(([v,t])=>`<option value="${esc(v)}">${esc(t)}</option>`).join('');if(options.some(([id])=>id===current().id))$('#field-managerId').value=current().id;$('#employee-capability').hidden=role!=='subadmin';if(role!=='subadmin')$('#field-alsoEmployee').checked=false;}
 if(event.target.id==='editor-format'){restoreEditorSelection();document.execCommand('formatBlock',false,event.target.value);state.dirty=true;}
});
document.addEventListener('mousedown',event=>{if(event.target.closest('[data-command]'))event.preventDefault();});
document.addEventListener('selectionchange',()=>{const editor=$('#cms-editor');const s=window.getSelection();if(editor&&s.rangeCount&&editor.contains(s.getRangeAt(0).commonAncestorContainer))savedSelection=s.getRangeAt(0).cloneRange();});
document.addEventListener('paste',event=>{if(event.target.closest('#cms-editor')){event.preventDefault();const html=event.clipboardData.getData('text/html');const text=event.clipboardData.getData('text/plain');document.execCommand('insertHTML',false,html?S.sanitizeHtml(html):esc(text).replace(/\n/g,'<br>'));state.dirty=true;updateEditorCount();}});
document.addEventListener('click',event=>{if(event.target.id==='nav-shade')closeMenu();});
document.addEventListener('keydown',event=>{if(event.key==='Escape')closeMenu();});
window.addEventListener('hashchange',()=>{if(state.dirty){const destination=location.hash;history.replaceState(null,'',lastHash||'#overview');confirmAction('Leave without saving?','Your unsaved changes will be discarded.',()=>go(destination));}else route();});
window.addEventListener('beforeunload',event=>{if(state.dirty){event.preventDefault();event.returnValue='';}});
window.addEventListener('storage',async event=>{if(event.key===C.storageKey&&['contacts','contact-enquiry'].includes(state.page)&&current()){render();return;}if(!event.key||event.key===S.storageKey){try{if(!current()){state.dirty=false;loginView('Your session ended or your access changed. Please sign in again.');}else if(!state.dirty){await S.init();render();}else toast('Administration data changed in another tab. Reload before saving.');}catch(error){report(error);}}});
$('#admin-dialog').addEventListener('close',()=>{confirmation=null;});
(async()=>{try{if(!S)throw Error('Administration data service did not load. Reload the page.');await S.init();route();}catch(err){$('#app').innerHTML=`<div class="loading-screen"><h1>Unable to open Administration</h1><p>${esc(err.message)}</p><p>Use a modern browser on localhost and allow browser storage.</p><a href="../index.html">Back to the website</a></div>`;}})();
})();
